css:
*{box-sizing:border-box;margin:0;padding:0}
:root{
  --canvas:#E9F1EB; --panel:#FFFFFF; --panel2:#F5FAF6;
  --forest:#12492C; --deep:#0E3A23; --mid:#2C7A50; --mid2:#3E9268; --leaf:#6FBF44;
  --mint:#D9EBDF; --mint2:#EBF5EE; --band:#DFEDE3;
  --ink:#14301F; --ink2:#3C5748; --muted:#63806F;
  --rule:#BFD6C7; --rule2:#D7E8DC;
  --gold:#A67C00; --gold-bg:#FBF2D9; --gold-line:#DDC486; --gold-ink:#7A5B00;
  --teal:#1B6C76; --teal-bg:#DDEEF0; --teal-line:#AFD3D7;
  --alert:#A63A28; --alert-bg:#FAE6E1; --alert-line:#E7C0B6;
  --warn:#8E6408; --warn-bg:#FBF0D6; --warn-line:#E3CE96;
  --plum:#6A3B7A; --plum-bg:#F0E7F3;
  --shadow:0 1px 2px rgba(14,58,35,.10),0 6px 20px rgba(14,58,35,.09);
}
html{scroll-behavior:smooth}
body{font-family:'Segoe UI',Tahoma,Arial,sans-serif;font-size:13px;line-height:1.45;background:var(--canvas);color:var(--ink);-webkit-font-smoothing:antialiased}
h1,h2,h3,.serif{font-family:Georgia,'Times New Roman',serif}
::selection{background:#BEE0CB}
button,input,select{font-family:inherit}
:focus-visible{outline:2px solid var(--mid);outline-offset:1px}

/* ---------- TOP BAR ---------- */
.topbar{background:linear-gradient(100deg,#0E3A23 0%,#17542F 45%,#2C7A50 100%);color:#fff;padding:0 15px;height:56px;display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:400;box-shadow:0 2px 10px rgba(14,58,35,.3)}
.brandmark{width:36px;height:36px;border-radius:9px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.34);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:15px;flex-shrink:0}
.brandmark span{color:var(--leaf)}
.tb-title{font-size:15px;font-weight:700;letter-spacing:.3px;line-height:1.15}
.tb-sub{font-size:10px;color:rgba(255,255,255,.75);margin-top:1px}
.tb-right{margin-left:auto;display:flex;align-items:center;gap:9px}
.tb-clock{font-size:10px;text-align:right;color:rgba(255,255,255,.82);line-height:1.4}
.tb-user{display:flex;align-items:center;gap:7px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.26);padding:4px 11px 4px 4px;border-radius:20px}
.tb-user .av{width:26px;height:26px;border-radius:50%;background:var(--gold);display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;color:#fff}
.tb-user .nm{font-size:11.5px;font-weight:600;line-height:1.1}
.tb-user .rl{font-size:10px;color:rgba(255,255,255,.75)}
.pill{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.3);padding:3px 10px;border-radius:14px;font-size:10px;font-weight:600}
.cartbtn{position:relative;background:var(--gold);border:1px solid #C9A63B;color:#fff;font-weight:700;font-size:11.5px;padding:7px 13px;border-radius:8px;cursor:pointer;display:flex;align-items:center;gap:7px}
.cartbtn:hover{filter:brightness(1.08)}
.cartbtn .cn{background:#fff;color:var(--gold-ink);border-radius:11px;padding:0 7px;font-size:10.5px;font-weight:800;min-width:20px;text-align:center}

/* ---------- TABS ---------- */
.tabbar{background:var(--panel);border-bottom:1px solid var(--rule);display:flex;align-items:stretch;position:sticky;top:56px;z-index:390;padding:0 12px}
.tab{border:none;background:none;padding:0 20px;height:44px;display:flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;letter-spacing:.4px;color:var(--ink2);cursor:pointer;border-bottom:3px solid transparent;text-transform:uppercase}
.tab:hover{color:var(--forest);background:var(--mint2)}
.tab.on{color:var(--forest);border-bottom-color:var(--mid);background:linear-gradient(180deg,#fff,var(--mint2))}
.tab .cnt{font-size:10px;background:var(--mint);color:var(--forest);border:1px solid var(--rule);padding:1px 7px;border-radius:10px;font-weight:800}
.tabbar .spacer{margin-left:auto;display:flex;align-items:center;gap:8px;padding-right:2px}
.unit-toggle{display:flex;border:1px solid var(--rule);border-radius:7px;overflow:hidden}
.unit-toggle button{border:none;background:#fff;padding:5px 10px;font-size:11px;color:var(--ink2);cursor:pointer;font-weight:600}
.unit-toggle button.on{background:var(--mid);color:#fff}
.unit-toggle button+button{border-left:1px solid var(--rule)}
.page{display:none;padding:14px 15px 70px}
.page.on{display:block}

/* ---------- FILTERS ---------- */
.filterwrap{background:var(--panel);border:1px solid var(--rule);border-radius:11px;box-shadow:var(--shadow);margin-bottom:13px;overflow:hidden}
.fw-head{display:flex;align-items:center;gap:10px;padding:9px 13px;background:linear-gradient(90deg,var(--band),#fff);border-bottom:1px solid var(--rule)}
.fw-head .t{font-size:12px;font-weight:800;letter-spacing:.6px;color:var(--forest);text-transform:uppercase}
.fw-head .hint{font-size:11px;color:var(--muted)}
.fw-body{padding:11px 13px 12px}
.frow{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end}
.frow+.frow{margin-top:10px;padding-top:10px;border-top:1px dashed var(--rule)}
.fld{display:flex;flex-direction:column;gap:3px;min-width:0}
.fld label{font-size:10px;font-weight:800;letter-spacing:.5px;color:var(--ink2);text-transform:uppercase}
.fld select,.fld input{border:1px solid var(--rule);border-radius:7px;padding:6px 9px;font-size:12.5px;background:#fff;color:var(--ink);min-width:132px}
.fld select:hover,.fld input:hover{border-color:var(--mid2)}
.searchfld{position:relative;flex:1 1 330px}
.searchfld input{width:100%;padding-left:30px;font-size:13px}
.searchfld .mag{position:absolute;left:9px;top:25px;font-size:13px;color:var(--muted)}
.detect{margin-top:7px;font-size:11px;color:var(--ink2);display:flex;gap:6px;flex-wrap:wrap;align-items:center;min-height:18px}
.detect:empty{display:none!important;margin:0;padding:0;min-height:0}
.chip{display:inline-flex;align-items:center;gap:5px;background:var(--mint);border:1px solid var(--rule);color:var(--forest);padding:2px 9px;border-radius:12px;font-size:10.5px;font-weight:700;cursor:pointer}
.chip:hover{background:#CBE3D3}
.chip.gold{background:var(--gold-bg);border-color:var(--gold-line);color:var(--gold-ink)}
.chip.x{background:#fff}
.btn{border:1px solid var(--rule);background:#fff;color:var(--ink);padding:7px 13px;border-radius:7px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px}
.btn:hover{border-color:var(--mid2);background:var(--mint2)}
.btn.primary{background:linear-gradient(180deg,var(--mid2),var(--mid));border-color:var(--forest);color:#fff}
.btn.primary:hover{filter:brightness(1.07)}
.btn.leaf{background:var(--mint);border-color:var(--rule);color:var(--forest)}
.btn.gold{background:var(--gold-bg);border-color:var(--gold-line);color:var(--gold-ink)}
.btn.danger{background:var(--alert-bg);border-color:var(--alert-line);color:var(--alert)}
.btn.sm{padding:4px 9px;font-size:11px;border-radius:6px}
.reopen{display:none;width:100%;justify-content:center}
.reopen.on{display:flex}
.reopen button{width:150px;border:1px solid var(--rule);border-top:none;border-radius:0 0 10px 10px;background:#fff;padding:4px 0;font-size:11px;color:var(--forest);cursor:pointer;font-weight:700}

/* ---------- FLOW SPINE ---------- */
.spine{display:flex;margin-bottom:13px;flex-wrap:wrap}
.step{flex:1 1 190px;background:var(--panel);border:1px solid var(--rule);padding:10px 15px 10px 25px;position:relative;min-width:180px}
.step:first-child{border-radius:11px 0 0 11px;padding-left:15px}
.step:last-child{border-radius:0 11px 11px 0}
.step+.step{border-left:none}
.step::before{content:"";position:absolute;left:-1px;top:0;bottom:0;width:13px;background:var(--canvas);clip-path:polygon(0 0,100% 50%,0 100%,0 0);z-index:2}
.step::after{content:"";position:absolute;left:1px;top:0;bottom:0;width:13px;background:var(--rule);clip-path:polygon(0 0,100% 50%,0 100%,0 0);z-index:1}
.step:first-child::before,.step:first-child::after{display:none}
.step .lbl{font-size:10px;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:var(--ink2);display:flex;align-items:center;gap:6px}
.step .qty{font-family:Georgia,serif;font-size:23px;font-weight:700;line-height:1.15;margin-top:3px;color:var(--forest)}
.step .qty small{font-size:11px;font-family:'Segoe UI',sans-serif;color:var(--muted);font-weight:600}
.step .val{font-size:12.5px;font-weight:800;margin-top:1px}
.step .sub{font-size:10.5px;color:var(--muted);margin-top:2px}
.step.s1{background:linear-gradient(180deg,#fff,var(--teal-bg));border-color:var(--teal-line)} .step.s1 .qty,.step.s1 .val{color:var(--teal)}
.step.s2{background:linear-gradient(180deg,#fff,var(--mint2))} .step.s2 .val{color:var(--mid)}
.step.s3{background:linear-gradient(180deg,#fff,var(--warn-bg));border-color:var(--warn-line)} .step.s3 .qty,.step.s3 .val{color:var(--warn)}
.step.s4{background:linear-gradient(180deg,#fff,var(--alert-bg));border-color:var(--alert-line)} .step.s4 .qty,.step.s4 .val{color:var(--alert)}
.step.s5{background:linear-gradient(180deg,#fff,var(--gold-bg));border-color:var(--gold-line)} .step.s5 .qty{color:var(--forest)} .step.s5 .val{color:var(--gold-ink)}

/* ---------- SECTIONS ---------- */
.sec{background:var(--panel);border:1px solid var(--rule);border-radius:10px;margin-bottom:12px;overflow:hidden;box-shadow:var(--shadow)}
.sec-h{display:flex;align-items:center;gap:10px;padding:9px 13px;cursor:pointer;background:linear-gradient(90deg,var(--band) 0%,#fff 65%);border-bottom:1px solid var(--rule);user-select:none}
.sec-h:hover{background:linear-gradient(90deg,var(--mint) 0%,#fff 72%)}
.sec-h .ar{font-size:10px;color:var(--mid);transition:transform .18s;width:12px;flex-shrink:0}
.sec.closed .sec-h{border-bottom-color:transparent}
.sec.closed .ar{transform:rotate(-90deg)}
.sec.closed .sec-b{display:none}
.sec-h .ttl{font-family:Georgia,serif;font-size:15px;font-weight:700;color:var(--deep);letter-spacing:.2px}
.sec-h .note{font-size:11px;color:var(--muted);border-left:1px solid var(--rule);padding-left:10px}
.sec-h .rt{margin-left:auto;display:flex;align-items:center;gap:7px}
.badge{font-size:10px;font-weight:700;padding:2px 8px;border-radius:11px;background:var(--mint);color:var(--forest);border:1px solid var(--rule);white-space:nowrap}
.badge.gold{background:var(--gold-bg);border-color:var(--gold-line);color:var(--gold-ink)}
.badge.alert{background:var(--alert-bg);border-color:var(--alert-line);color:var(--alert)}
.badge.teal{background:var(--teal-bg);border-color:var(--teal-line);color:var(--teal)}
.sec-b.pad{padding:12px 13px 14px}
.subhead{font-size:10.5px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:var(--forest);padding:8px 13px 6px;border-top:1px solid var(--rule2);background:var(--panel2)}

/* ---------- TABLES ---------- */
.tw{overflow:auto;border-top:1px solid var(--rule2)}
.tw.cap{max-height:470px}
table.rt{width:100%;border-collapse:separate;border-spacing:0;font-size:12.5px}
table.rt th{position:sticky;top:0;z-index:5;background:linear-gradient(180deg,#E4F0E8,#D3E6DA);color:var(--deep);font-size:10px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;text-align:left;padding:8px 9px;border-bottom:1px solid var(--rule);border-right:1px solid #C9DED0;white-space:nowrap;cursor:pointer;vertical-align:bottom}
table.rt th:hover{background:#C9E1D3}
table.rt th .sarr{opacity:.35;font-size:9px;margin-left:3px}
table.rt th.sorted .sarr{opacity:1;color:var(--forest)}
table.rt th.num,table.rt td.num{text-align:right}
table.rt td{padding:6px 9px;border-bottom:1px solid var(--rule2);border-right:1px solid #EBF3EE;vertical-align:top;white-space:nowrap}
table.rt td.wrap{white-space:normal;word-break:break-word;line-height:1.35}
table.rt td.num{font-variant-numeric:tabular-nums}
table.rt tbody tr:nth-child(even){background:#F7FBF8}
table.rt tbody tr:hover{background:#E7F3EB}
table.rt tbody tr.clickable{cursor:pointer}
table.rt tbody tr.clickable:hover{box-shadow:inset 3px 0 0 var(--mid)}
table.rt tfoot td{position:sticky;bottom:0;background:#DCEBE1;font-weight:800;color:var(--deep);border-top:1.5px solid var(--rule);border-bottom:none;z-index:4}
.nm{color:var(--deep);font-weight:700}
.lnk{color:var(--deep);font-weight:700;cursor:pointer;border-bottom:1px dotted var(--mid)}
.lnk:hover{color:var(--mid);background:#E2F1E8}
.vlnk{color:var(--gold-ink);font-weight:700;cursor:pointer;border-bottom:1px dotted var(--gold-line)}
.vlnk:hover{background:var(--gold-bg)}
.sub2{display:block;font-size:10px;color:var(--muted);font-weight:400;margin-top:1px}
.mono{font-family:Consolas,'Courier New',monospace;font-size:11px;color:var(--ink2)}
.alt{color:var(--plum);font-weight:700;font-size:11px}
.alt.single{color:var(--alert)}
.tag{display:inline-block;padding:1px 7px;border-radius:10px;font-size:10px;font-weight:700;border:1px solid;white-space:nowrap}
.tag.ok{background:#DFF0E2;border-color:#B9DCC0;color:#1D6B31}
.tag.warn{background:var(--warn-bg);border-color:var(--warn-line);color:var(--warn)}
.tag.bad{background:var(--alert-bg);border-color:var(--alert-line);color:var(--alert)}
.tag.info{background:var(--teal-bg);border-color:var(--teal-line);color:var(--teal)}
.tag.mute{background:#EDF2EE;border-color:var(--rule);color:var(--ink2)}
.tag.plum{background:var(--plum-bg);border-color:#D7C2DE;color:var(--plum)}
.mv{display:inline-block;padding:1px 7px;border-radius:10px;font-size:10px;font-weight:800;border:1px solid}
.mv.H{background:#DDF0E1;border-color:#A9D3B4;color:#155F2C}
.mv.M{background:var(--warn-bg);border-color:var(--warn-line);color:var(--warn)}
.mv.L{background:#E8EEF1;border-color:#C4D4DC;color:#3F5A68}
.money{color:var(--gold-ink);font-weight:700}
.inq{color:var(--teal);font-weight:700}
.outq{color:var(--mid);font-weight:700}
.retq{color:var(--warn);font-weight:700}
.dmg{color:var(--alert);font-weight:700}
.bal{color:var(--deep);font-weight:800}
.empty{padding:24px;text-align:center;color:var(--muted);font-size:12.5px}
.empty b{display:block;color:var(--ink2);font-size:13.5px;margin-bottom:4px}
.addbtn{border:1px solid var(--gold-line);background:var(--gold-bg);color:var(--gold-ink);font-size:10.5px;font-weight:800;padding:3px 8px;border-radius:6px;cursor:pointer;white-space:nowrap}
.addbtn:hover{background:#F5E7BE}
.addbtn.inlist{background:var(--mint);border-color:var(--rule);color:var(--forest)}

/* =====================================================================
   ⭐ STOCK ITEM CELL — clean 3-tier layout with highlighted name
   ===================================================================== */
.item-cell{
  display:flex;
  flex-direction:column;
  gap:3px;
  min-width:0;
  padding:2px 0;
}
.item-cell .ic-name{
  display:inline-block;
  max-width:100%;
  background:linear-gradient(180deg,#EAF6EE 0%,#DDF0E4 100%);
  border-left:3px solid #2C7A50;
  border-radius:4px;
  padding:3px 9px 3px 7px;
  font-weight:800;
  color:#0E3A23;
  font-size:13px;
  line-height:1.25;
  box-shadow:0 1px 2px rgba(20,80,50,.06);
  transition:background .15s,border-color .15s,transform .15s;
  white-space:normal;
  word-break:break-word;
  cursor:pointer;
}
.item-cell .ic-name:hover{
  background:linear-gradient(180deg,#DFF1E5 0%,#C9E8D4 100%);
  border-left-color:#12492C;
  transform:translateX(1px);
}
.item-cell .ic-meta{
  font-size:10.5px;
  color:var(--muted);
  line-height:1.3;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  padding-left:6px;
}
.item-cell .ic-meta .sep{opacity:.5;padding:0 2px}
.item-cell .ic-meta .mono{
  font-family:Consolas,'Courier New',monospace;
  color:var(--ink2);
  font-weight:600;
}
.item-cell .ic-tags{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
  margin-top:1px;
  padding-left:6px;
  min-height:14px;
}
.item-cell .mv-dot{
  font-size:11px;
  line-height:1;
  display:inline-flex;
  align-items:center;
  gap:3px;
  cursor:help;
}
.item-cell .mv-dot.h{color:#155F2C}
.item-cell .mv-dot.m{color:#8E6408}
.item-cell .mv-dot.l{color:#8395A0}
.item-cell .src-warn{
  font-size:10px;
  color:#8E6408;
  background:#FBF0D6;
  border:1px solid #E3CE96;
  border-radius:8px;
  padding:0 6px;
  font-weight:700;
  line-height:1.5;
  white-space:nowrap;
}
.item-cell .addbtn{
  margin-left:auto;
  align-self:flex-start;
}
/* Stock Item column — wider so highlight has room */
table.rt th.w-item,
table.rt td.w-item{
  width:300px;
  min-width:300px;
  max-width:300px;
}
/* Soft panel behind the first column so the highlighted name pops */
#s1 table.rt td:first-child{background:#F4FBF6}
#s1 table.rt tbody tr:nth-child(even) td:first-child{background:#EEF7F0}
#s1 table.rt tbody tr:hover td:first-child{background:#E3F3E8}

/* branch colours */
.b-HO{color:#8E6A00}.b-CN{color:#22683A}.b-SRN{color:#0F6A64}.b-MP{color:#5B3C86}.b-BH{color:#93356B}
.b-HN{color:#14549E}.b-DN{color:#A8551A}.b-GB{color:#0B6C7A}.b-VW{color:#4B7A22}.b-VZ{color:#6B4A33}
.b-NLR{color:#7A3FA8}.b-KP{color:#0A5F94}
.bdot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px;background:currentColor;vertical-align:middle}

/* ---------- BARS ---------- */
.barrow{display:grid;grid-template-columns:130px 1fr 138px;gap:9px;align-items:center;padding:3px 0}
.barrow .bn{font-size:11.5px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bartrack{background:#E4EDE7;border-radius:5px;height:15px;overflow:hidden;border:1px solid var(--rule2)}
.barfill{height:100%;border-radius:4px;background:linear-gradient(90deg,var(--mid),#5FB77F)}
.barfill.gold{background:linear-gradient(90deg,var(--gold),#D9B84E)}
.barfill.teal{background:linear-gradient(90deg,var(--teal),#5FA8B0)}
.barval{font-size:11px;font-weight:700;text-align:right;font-variant-numeric:tabular-nums;color:var(--ink2)}
.rank{display:inline-flex;width:19px;height:19px;border-radius:50%;background:var(--mint);color:var(--forest);align-items:center;justify-content:center;font-size:10px;font-weight:800;margin-right:6px;border:1px solid var(--rule)}
.rank.r1{background:var(--gold-bg);border-color:var(--gold-line);color:var(--gold-ink)}
.colchart{display:flex;align-items:flex-end;gap:5px;height:118px;padding:6px 2px 0;border-bottom:1px solid var(--rule)}
.colchart .cbar{flex:1;display:flex;justify-content:center;align-items:flex-end;gap:2px;min-width:0;height:100%}
.colchart .cb{width:46%;background:linear-gradient(180deg,var(--mid),#6FB98D);border-radius:3px 3px 0 0;min-height:2px}
.colchart .cb.g{background:linear-gradient(180deg,var(--gold),#E0C877)}
.colx{display:flex;gap:5px;padding-top:4px}
.colx div{flex:1;text-align:center;font-size:10px;color:var(--muted);white-space:nowrap;overflow:hidden}

/* ---------- 360 ---------- */
.pickbar{background:var(--panel);border:1px solid var(--rule);border-radius:11px;padding:12px 13px;margin-bottom:13px;box-shadow:var(--shadow)}
.pb-title{font-family:Georgia,serif;font-size:16px;color:var(--deep);font-weight:700}
.pb-sub{font-size:11.5px;color:var(--muted);margin:2px 0 10px}
.sugg{position:absolute;z-index:60;top:100%;left:0;right:0;background:#fff;border:1px solid var(--rule);border-radius:0 0 9px 9px;box-shadow:var(--shadow);max-height:280px;overflow:auto;display:none}
.sugg.on{display:block}
.sugg div{padding:7px 11px;font-size:12.5px;cursor:pointer;border-bottom:1px solid var(--rule2);display:flex;gap:8px;align-items:center}
.sugg div:hover{background:var(--mint2)}
.sugg .k{font-size:10px;font-weight:800;padding:1px 6px;border-radius:9px;background:var(--mint);color:var(--forest);border:1px solid var(--rule)}
.sugg .k.v{background:var(--gold-bg);border-color:var(--gold-line);color:var(--gold-ink)}
.hero{background:linear-gradient(120deg,#fff 55%,var(--mint2));border:1px solid var(--rule);border-left:5px solid var(--mid);border-radius:11px;padding:14px 15px;display:flex;gap:15px;align-items:flex-start;margin-bottom:13px;box-shadow:var(--shadow);flex-wrap:wrap}
.hero.vend{border-left-color:var(--gold);background:linear-gradient(120deg,#fff 55%,var(--gold-bg))}
.pic{width:90px;height:90px;border-radius:13px;border:1px solid var(--rule);background:linear-gradient(160deg,var(--mint),#fff);display:flex;align-items:center;justify-content:center;font-size:42px;flex-shrink:0;box-shadow:inset 0 0 0 4px #fff}
.pic.avatar{border-radius:50%;background:linear-gradient(150deg,#D3AB3E,var(--gold));color:#fff;font-family:Georgia,serif;font-size:31px;font-weight:700}
.hero .hmain{flex:1 1 330px;min-width:270px}
.hero h2{font-size:21px;color:var(--deep);line-height:1.2}
.hero .hcode{font-size:11.5px;color:var(--ink2);margin-top:3px;display:flex;gap:9px;flex-wrap:wrap;align-items:center}
.hero .hmeta{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}
.mchip{background:#fff;border:1px solid var(--rule);border-radius:8px;padding:5px 10px;min-width:96px}
.mchip .k{font-size:10px;letter-spacing:.5px;text-transform:uppercase;color:var(--muted);font-weight:700}
.mchip .v{font-size:13px;font-weight:700;color:var(--deep);margin-top:1px}
.mchip .s{font-size:10px;color:var(--muted)}
.mchip.gold{background:var(--gold-bg);border-color:var(--gold-line)}
.mchip.gold .v{color:var(--gold-ink)}
.bigstock{flex:0 0 236px;border:1px solid var(--gold-line);border-radius:11px;padding:10px 14px;text-align:right;background:linear-gradient(160deg,#fff,var(--gold-bg))}
.bigstock .k{font-size:10px;font-weight:800;letter-spacing:.8px;text-transform:uppercase;color:var(--ink2)}
.bigstock .n{font-family:Georgia,serif;font-size:41px;font-weight:700;color:var(--deep);line-height:1.05;margin:2px 0}
.bigstock .n small{font-size:14px;color:var(--muted);font-family:'Segoe UI',sans-serif}
.bigstock .w{font-size:14px;font-weight:800;color:var(--gold-ink)}
.bigstock .sp{font-size:10.5px;color:var(--ink2);margin-top:4px;border-top:1px dashed var(--gold-line);padding-top:4px}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
@media(max-width:1080px){.grid3{grid-template-columns:1fr}}
.kv{display:grid;grid-template-columns:auto 1fr;gap:3px 12px;font-size:12.5px}
.kv .k{color:var(--muted);font-size:11px;white-space:nowrap}
.kv .v{font-weight:600;text-align:right;word-break:break-word;color:var(--ink)}
.note-line{font-size:11.5px;color:var(--ink2);background:var(--mint2);border:1px solid var(--rule2);border-radius:8px;padding:7px 10px;margin:11px 13px 12px}
.tline{position:relative;padding:2px 0 2px 20px;margin-left:8px;border-left:2px solid var(--rule)}
.tline .ev{position:relative;padding:6px 0 6px 4px;font-size:12px}
.tline .ev::before{content:"";position:absolute;left:-27px;top:11px;width:9px;height:9px;border-radius:50%;background:#fff;border:2px solid var(--mid)}
.tline .ev.buy::before{border-color:var(--teal)}
.tline .ev.ret::before{border-color:var(--warn)}
.tline .ev.cmp::before{border-color:var(--alert)}
.tline .ev .d{font-size:10px;color:var(--muted);font-weight:700}

/* ---------- CART DRAWER + MODAL ---------- */
.backdrop{position:fixed;inset:0;background:rgba(14,58,35,.38);opacity:0;pointer-events:none;transition:.2s;z-index:600}
.backdrop.on{opacity:1;pointer-events:auto}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(560px,96vw);background:var(--canvas);border-left:1px solid var(--rule);box-shadow:-6px 0 28px rgba(14,58,35,.25);transform:translateX(102%);transition:transform .24s ease;z-index:650;display:flex;flex-direction:column}
.drawer.on{transform:none}
.dr-head{background:linear-gradient(100deg,#0E3A23,#2C7A50);color:#fff;padding:12px 14px;display:flex;align-items:center;gap:10px}
.dr-head h3{font-size:16px}
.dr-head .s{font-size:10.5px;color:rgba(255,255,255,.8)}
.dr-head .x{margin-left:auto;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);color:#fff;border-radius:7px;padding:4px 10px;font-size:12px;cursor:pointer}
.dr-body{flex:1;overflow:auto;padding:12px}
.dr-foot{border-top:1px solid var(--rule);background:#fff;padding:10px 12px;display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.dr-foot .tot{margin-right:auto;font-size:12px;color:var(--ink2)}
.dr-foot .tot b{font-family:Georgia,serif;font-size:18px;color:var(--gold-ink);display:block}
.qtybox{display:inline-flex;align-items:center;border:1px solid var(--rule);border-radius:6px;overflow:hidden}
.qtybox button{border:none;background:var(--mint2);width:22px;height:24px;cursor:pointer;font-size:13px;color:var(--forest);font-weight:800}
.qtybox button:hover{background:var(--mint)}
.qtybox input{border:none;width:52px;text-align:center;font-size:12px;padding:3px;min-width:0}
.modal{position:fixed;top:50%;left:50%;transform:translate(-50%,-46%) scale(.97);background:#fff;border:1px solid var(--rule);border-top:4px solid var(--warn);border-radius:12px;box-shadow:0 16px 50px rgba(14,58,35,.3);width:min(460px,94vw);z-index:700;opacity:0;pointer-events:none;transition:.18s}
.modal.on{opacity:1;pointer-events:auto;transform:translate(-50%,-50%) scale(1)}
.modal h4{font-family:Georgia,serif;font-size:17px;color:var(--deep);padding:14px 16px 0}
.modal .mb{padding:8px 16px 14px;font-size:12.5px;color:var(--ink2);line-height:1.6}
.modal .mf{border-top:1px solid var(--rule2);padding:10px 14px;display:flex;gap:8px;justify-content:flex-end;background:var(--panel2);border-radius:0 0 11px 11px}
.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%) translateY(12px);background:var(--deep);color:#fff;padding:9px 18px;border-radius:22px;font-size:12.5px;box-shadow:0 6px 22px rgba(14,58,35,.34);opacity:0;pointer-events:none;transition:.25s;z-index:900}
.toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
.footer{text-align:center;font-size:10.5px;color:var(--muted);padding:16px 0 4px}

@media print{
  .topbar,.tabbar,.filterwrap,.reopen,.btn,.addbtn,.drawer,.backdrop{display:none!important}
  .sec{break-inside:avoid;box-shadow:none}
  .page{display:block!important}
  .item-cell .ic-name{background:#fff!important;border-left:2px solid #2C7A50!important;box-shadow:none!important}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}



/* =====================================================================
   REPORTS TAB — Client–Stock Report + Status Report (add-on block)
   ===================================================================== */
:root{
  --cSL:#3C7A1A;--cSLb:#E7F2DC;--cDM:#A8336B;--cDMb:#FBE3EE;--cHT:#1D5FA3;--cHTb:#E1EBF8;
  --cCO:#0A7B86;--cCOb:#DCF1F3;--cLR:#8A6500;--cLRb:#FAF0D0;--cSP:#6C3E9E;--cSPb:#EFE7F8;
  --tMT:#1F6B41;--tCON:#3F4E91;--tADV:#B4470E;
}
/* header + report switcher */
.sr-head{display:flex;gap:12px;align-items:stretch;flex-wrap:wrap;margin-bottom:13px}
.sr-title{flex:1 1 270px;min-width:240px;background:#fff;border:1px solid var(--rule);border-left:5px solid var(--mid);border-radius:11px;padding:12px 15px;box-shadow:var(--shadow)}
.sr-title h1{font-size:22px;color:var(--deep);line-height:1.2}
.sr-title p{font-size:12.5px;color:var(--ink2);margin-top:4px;line-height:1.45}
.sr-switch{flex:2 1 560px;display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media(max-width:760px){.sr-switch{grid-template-columns:1fr}}
.sr-sw{display:flex;align-items:center;gap:12px;text-align:left;border:1px solid var(--rule);background:#fff;border-radius:11px;padding:11px 14px;cursor:pointer;box-shadow:var(--shadow);color:var(--ink);font-family:inherit}
.sr-sw .ic{width:42px;height:42px;border-radius:10px;background:var(--mint);border:1px solid var(--rule);display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0}
.sr-sw b{display:block;font-family:Georgia,serif;font-size:16.5px;color:var(--deep)}
.sr-sw small{display:block;font-size:12px;color:var(--muted);margin-top:2px}
.sr-sw .n{margin-left:auto;font-size:12px;font-weight:800;background:var(--mint);border:1px solid var(--rule);color:var(--forest);border-radius:12px;padding:2px 10px;white-space:nowrap}
.sr-sw:hover{border-color:var(--mid2)}
.sr-sw.on{background:linear-gradient(110deg,#0E3A23,#1F6B41 60%,#2C7A50);border-color:var(--forest);color:#fff}
.sr-sw.on b{color:#fff}.sr-sw.on small{color:rgba(255,255,255,.82)}
.sr-sw.on .ic{background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.35)}
.sr-sw.on .n{background:#fff;color:var(--forest)}
.sr-rep{display:none}.sr-rep.on{display:block}
/* filter extras */
.sr-rep .fld select{max-width:230px}
.sr-tools{display:flex;gap:7px;flex-wrap:wrap;align-items:flex-end;margin-left:auto}
.sr-seg{display:inline-flex;border:1px solid var(--rule);border-radius:7px;overflow:hidden;background:#fff}
.sr-seg button{border:none;background:#fff;padding:7px 11px;font-size:12px;font-weight:700;color:var(--ink2);cursor:pointer;font-family:inherit}
.sr-seg button+button{border-left:1px solid var(--rule)}
.sr-seg button.on{background:var(--mid);color:#fff}
.sr-chk{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:700;color:var(--ink2);padding:6px 10px;border:1px dashed var(--rule);border-radius:7px;background:#fff;cursor:pointer;user-select:none}
.sr-chk input{accent-color:var(--mid);width:15px;height:15px}
.sr-dd{position:relative}
.sr-menu{position:absolute;right:0;top:calc(100% + 5px);background:#fff;border:1px solid var(--rule);border-radius:10px;box-shadow:0 10px 30px rgba(14,58,35,.2);min-width:250px;padding:5px;display:none;z-index:80}
.sr-menu.on{display:block}
.sr-menu button{display:flex;gap:10px;align-items:flex-start;width:100%;border:none;background:none;text-align:left;padding:8px 10px;border-radius:7px;cursor:pointer;font-family:inherit}
.sr-menu button:hover{background:var(--mint2)}
.sr-menu .mi{font-size:16px;line-height:1.1;width:20px;text-align:center}
.sr-menu b{display:block;font-size:12.5px;color:var(--deep)}
.sr-menu small{display:block;font-size:11px;color:var(--muted);margin-top:1px}
.sr-menu hr{border:none;border-top:1px solid var(--rule2);margin:4px 6px}
/* KPI tiles */
.sr-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(138px,1fr));gap:9px;margin-bottom:12px}
.sr-k{background:#fff;border:1px solid var(--rule);border-top:3px solid var(--mid);border-radius:10px;padding:8px 12px 9px;box-shadow:var(--shadow);min-width:0}
.sr-k .l{font-size:11.5px;color:var(--ink2);font-weight:700}
.sr-k .v{font-family:Georgia,serif;font-size:24px;font-weight:700;color:var(--deep);line-height:1.15;margin-top:2px}
.sr-k .s{font-size:11px;color:var(--muted);margin-top:1px}
.sr-k.g{border-top-color:#2E8B4E}.sr-k.g .v{color:#1D6B31}
.sr-k.a{border-top-color:#C99A1E}.sr-k.a .v{color:var(--warn)}
.sr-k.r{border-top-color:#C0533E}.sr-k.r .v{color:var(--alert)}
.sr-k.t{border-top-color:var(--teal)}.sr-k.t .v{color:var(--teal)}
.sr-k.m{border-top-color:#9DB3A6}.sr-k.m .v{color:var(--ink2)}
.sr-k.o{border-top-color:var(--gold)}.sr-k.o .v{color:var(--gold-ink)}
/* colour key */
.sr-key{display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center;background:#fff;border:1px solid var(--rule);border-radius:10px;padding:8px 12px;margin-bottom:12px;box-shadow:var(--shadow)}
.sr-key .kg{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.sr-key .kl{font-size:11px;font-weight:800;color:var(--ink2);margin-right:2px}
.sr-key .sep{width:1px;align-self:stretch;background:var(--rule2)}
/* category pill */
.cp{display:inline-flex;align-items:center;gap:5px;padding:1px 8px 1px 6px;border-radius:11px;font-size:11px;font-weight:700;border:1px solid;white-space:nowrap;line-height:1.5}
.cp i{width:8px;height:8px;border-radius:50%;background:currentColor;display:inline-block}
.cp.sl{color:var(--cSL);background:var(--cSLb);border-color:#C3DDAA}
.cp.dm{color:var(--cDM);background:var(--cDMb);border-color:#EDB9D0}
.cp.ht{color:var(--cHT);background:var(--cHTb);border-color:#B4CCEA}
.cp.co{color:var(--cCO);background:var(--cCOb);border-color:#A9D8DE}
.cp.lr{color:var(--cLR);background:var(--cLRb);border-color:#E6D08A}
.cp.sp{color:var(--cSP);background:var(--cSPb);border-color:#D2BDEA}
button.cp{cursor:pointer;font-family:inherit;font-size:11.5px;padding:3px 10px 3px 7px}
button.cp .c{background:#fff;border-radius:8px;padding:0 6px;font-size:10.5px;margin-left:2px;color:inherit}
button.cp.on{box-shadow:0 0 0 2px currentColor inset}
button.cp.dim{opacity:.45}
/* stock type badge (square, solid) */
.stb{display:inline-block;min-width:36px;text-align:center;padding:1px 6px;border-radius:4px;font-size:10.5px;font-weight:800;letter-spacing:.5px;color:#fff;vertical-align:1px}
.stb.mt{background:var(--tMT)}.stb.con{background:var(--tCON)}.stb.adv{background:var(--tADV)}
.stn{font-size:11px;color:var(--ink2);font-weight:600}
/* status badges */
.sbx{display:inline-block;padding:2px 9px;border-radius:11px;font-size:11px;font-weight:800;border:1px solid;white-space:nowrap}
.sbx.a{background:#DDF1E2;border-color:#A9D5B4;color:#1D6B31}
.sbx.p{background:var(--warn-bg);border-color:var(--warn-line);color:var(--warn)}
.sbx.r{background:var(--alert-bg);border-color:var(--alert-line);color:var(--alert)}
.sbx.w{background:#ECF0EE;border-color:#C9D6CE;color:#52685B}
.yn{display:inline-block;min-width:38px;text-align:center;padding:2px 8px;border-radius:5px;font-size:11.5px;font-weight:800;border:1px solid}
.yn.y{background:#DDF1E2;border-color:#A9D5B4;color:#1D6B31}
.yn.n{background:var(--alert-bg);border-color:var(--alert-line);color:var(--alert)}
.pq{display:inline-block;min-width:30px;text-align:center;background:var(--warn-bg);border:1px solid var(--warn-line);color:var(--warn);font-weight:800;border-radius:5px;padding:1px 7px;font-size:13px}
.pz{color:#1D6B31;font-weight:800}
.aq{color:#1D6B31;font-weight:800}.rq{color:var(--alert);font-weight:800}.rq.z{color:#9DB3A6;font-weight:600}
.gf{display:inline-block;padding:1px 7px;border-radius:4px;font-size:10.5px;font-weight:800;margin-right:4px;border:1px solid}
.gf.ho{background:var(--gold-bg);border-color:var(--gold-line);color:var(--gold-ink)}
.gf.br{background:var(--teal-bg);border-color:var(--teal-line);color:var(--teal)}
.aj{color:var(--warn);font-weight:800}
.df{display:inline-block;min-width:34px;text-align:center;border-radius:5px;padding:1px 7px;font-weight:800;font-size:12.5px;border:1px solid}
.df.ok{background:#DDF1E2;border-color:#A9D5B4;color:#1D6B31}
.df.bad{background:var(--alert-bg);border-color:var(--alert-line);color:var(--alert)}
.brm{font-weight:700;font-size:11.5px;white-space:nowrap}
.brm.big{font-size:13.5px}
.x2.rb{color:var(--ink);font-weight:600;font-size:12px;margin-top:3px}
/* table */
.sr-tw{overflow:auto;max-height:640px;border-top:1px solid var(--rule2)}
table.srt{width:100%;border-collapse:separate;border-spacing:0;font-size:13px;color:var(--ink)}
table.srt th{position:sticky;top:0;z-index:3;background:linear-gradient(180deg,#E4F0E8,#D3E6DA);color:var(--deep);font-size:11px;font-weight:800;letter-spacing:.3px;text-transform:uppercase;text-align:left;padding:8px 8px;border-bottom:1px solid var(--rule);border-right:1px solid #C9DED0;vertical-align:bottom;line-height:1.3}
table.srt th.s{cursor:pointer}
table.srt th.s:hover{background:#C9E1D3}
table.srt th i{font-style:normal;font-size:9.5px;opacity:.4;margin-left:4px}
table.srt th.on i{opacity:1;color:var(--forest)}
table.srt td{padding:7px 8px;border-bottom:1px solid var(--rule2);border-right:1px solid #EBF3EE;vertical-align:top;line-height:1.38;background:#fff}
table.srt th.n,table.srt td.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
table.srt th.n{white-space:normal}
table.srt[data-t]{table-layout:fixed;min-width:1180px}
table.srt th.ctr,table.srt td.ctr{text-align:center}
table.srt td.dt{white-space:nowrap;font-variant-numeric:tabular-nums}
table.srt tbody tr:nth-child(even) td{background:#F8FBF9}
table.srt tbody tr:hover td{background:#EAF5EE}
table.srt tbody td:first-child{border-left:4px solid transparent}
table.srt tr.k-sl td:first-child{border-left-color:var(--cSL)}
table.srt tr.k-dm td:first-child{border-left-color:var(--cDM)}
table.srt tr.k-ht td:first-child{border-left-color:var(--cHT)}
table.srt tr.k-co td:first-child{border-left-color:var(--cCO)}
table.srt tr.k-lr td:first-child{border-left-color:var(--cLR)}
table.srt tr.k-sp td:first-child{border-left-color:var(--cSP)}
table.srt tr.rj td{color:#6E7F75}
table.srt tfoot td{position:sticky;bottom:0;background:#DCEBE1;font-weight:800;color:var(--deep);border-top:1.5px solid var(--rule);border-bottom:none;z-index:2;padding:8px}
table.srt tr.grp td{background:linear-gradient(90deg,#DCEEE2,#F3F9F5)!important;border-top:2px solid var(--mid);border-left:4px solid var(--forest)!important;padding:8px 10px}
.g-row{display:flex;flex-wrap:wrap;gap:6px 16px;align-items:center}
.g-row .g-nm{font-family:Georgia,serif;font-size:15px;font-weight:700;color:var(--deep)}
.g-row .g-mt{font-size:12px;color:var(--ink2)}
.g-row .g-fig{margin-left:auto;display:flex;gap:14px;font-size:12px;color:var(--ink2);flex-wrap:wrap}
.g-row .g-fig b{font-size:14px;color:var(--deep)}
.g-row .g-fig .gp b{color:var(--warn)}.g-row .g-fig .ge b{color:#1D6B31}
.nm1{color:var(--deep);font-weight:700;font-size:13.5px}
.it1{color:var(--deep);font-weight:700}
.it1[data-item]{cursor:pointer;border-bottom:1px dotted var(--mid)}
.it1[data-item]:hover{color:var(--mid)}
.qx{font-weight:800;color:var(--forest);white-space:nowrap}
.x2{display:block;font-size:11px;color:var(--muted);margin-top:2px;font-weight:400}
.x2 b{color:var(--ink2)}
.fc{color:var(--plum)!important;font-weight:600!important}
.sr-note{font-size:12px;color:var(--ink2);background:var(--mint2);border-top:1px solid var(--rule2);padding:8px 13px;line-height:1.5}
.sr-note b{color:var(--deep)}
/* client statement card */
.sr-stmt{background:linear-gradient(120deg,#fff 50%,var(--mint2));border:1px solid var(--rule);border-left:5px solid var(--forest);border-radius:11px;padding:14px 16px;margin-bottom:12px;box-shadow:var(--shadow);display:grid;grid-template-columns:minmax(260px,1.1fr) 2fr;gap:14px 20px;align-items:center}
@media(max-width:900px){.sr-stmt{grid-template-columns:1fr}}
.st-a{display:flex;gap:13px;align-items:center;min-width:0}
.st-av{width:58px;height:58px;border-radius:50%;background:linear-gradient(150deg,#2C7A50,#12492C);color:#fff;font-family:Georgia,serif;font-size:22px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.st-k{font-size:11.5px;font-weight:800;color:var(--mid)}
.sr-stmt h2{font-size:21px;color:var(--deep);line-height:1.2}
.st-m{font-size:12px;color:var(--ink2);margin-top:2px}
.st-t{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px;font-size:12px;color:var(--ink2);align-items:center}
.st-f{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px}
