function calMonthStart(offset){
  const d=new Date(TODAY.getFullYear(),TODAY.getMonth()+offset,1);
  return iso(d);
}
function calMonthEnd(offset){
  const d=new Date(TODAY.getFullYear(),TODAY.getMonth()+offset+1,0);
  return iso(d);
}

/* LIFE business month = 6th of month -> 5th of next month.
   Use LOCAL date parts. toISOString() shifts IST midnight to the previous UTC date. */
function lifeLocalYMD(d){
  return String(d.getFullYear())+'-'+
    String(d.getMonth()+1).padStart(2,'0')+'-'+
    String(d.getDate()).padStart(2,'0');
}
function lifeBusinessMonthStart(offset){
  offset=Number(offset||0);
  const baseMonth=TODAY.getDate()>=6?TODAY.getMonth():TODAY.getMonth()-1;
  return lifeLocalYMD(new Date(TODAY.getFullYear(),baseMonth+offset,6,12,0,0));
}
function lifeBusinessMonthEnd(offset){
  offset=Number(offset||0);
  const baseMonth=TODAY.getDate()>=6?TODAY.getMonth():TODAY.getMonth()-1;
  return lifeLocalYMD(new Date(TODAY.getFullYear(),baseMonth+offset+1,5,12,0,0));
}
function lifeBusinessPeriodLabel(from,to){
  return dmy(from)+' → '+dmy(to);
}

const PURCHASES=[],LIFETIME_PURCHASES=[],PURCHASE_INVOICES=[],DISPATCH=[],RETURNS=[],CONSUMPTION=[],COMPLAINTS=[],PAYMENTS=[],ADJUST=[],BOOKINGS=[];
