const HO_STOCK={},BRANCH_STOCK={},CONSUMED={},HO_DMG={},BR_DMG={},MOVE={};
const LIVE_STOCK_WARNINGS={};

/* V22: Browser-side sanity guard for live Bin quantities.
   We never invent a replacement quantity. If ERP sends a non-finite or
   clearly impossible Bin value, that cell is treated as unavailable (0 for
   arithmetic) and recorded in LIVE_STOCK_WARNINGS instead of displaying
   billions as if they were valid stock. */
function lifeSafeBinQty(itemCode,warehouse,value){
  const n=Number(value);
  const key=String(itemCode||'')+'||'+String(warehouse||'');
  if(!Number.isFinite(n)){
    LIVE_STOCK_WARNINGS[key]={item:itemCode,warehouse:warehouse,value:value,reason:'non-finite Bin.actual_qty'};
    return 0;
  }
  // Physical stock quantities beyond this are treated as a data-integrity exception.
  // This does not manufacture another number; it suppresses only the corrupt value.
  if(Math.abs(n)>10000000){
    LIVE_STOCK_WARNINGS[key]={item:itemCode,warehouse:warehouse,value:n,reason:'implausible Bin.actual_qty'};
    return 0;
  }
  return n;
}
function lifeHasStockWarning(itemCode){
  const p=String(itemCode||'')+'||';
  return Object.keys(LIVE_STOCK_WARNINGS).some(k=>k.indexOf(p)===0);
}
const branchQty=(ic,bc)=>nval((BRANCH_STOCK[ic]||{})[bc]);
const branchDmgQty=(ic,bc)=>nval((BR_DMG[ic]||{})[bc]);
ITEMS.forEach(it=>{
  const ic=it.code;
  const buy=PURCHASES.filter(p=>p.item===ic).reduce((s,p)=>s+p.qty,0);
  const sent=DISPATCH.filter(d=>d.item===ic).reduce((s,d)=>s+d.qty,0);
  const good=RETURNS.filter(r=>r.item===ic&&r.cond!=='Damaged — scrapped').reduce((s,r)=>s+r.qty,0);
  const hd=ADJUST.filter(a=>a.item===ic&&a.loc==='HO').reduce((s,a)=>s+a.qty,0);
  HO_DMG[ic]=hd;HO_STOCK[ic]=Math.max(0,buy-sent+good-hd);
  BRANCH_STOCK[ic]={};CONSUMED[ic]={};BR_DMG[ic]={};
  BR.forEach(b=>{
    const rec=DISPATCH.filter(d=>d.item===ic&&d.branch===b.code&&d.status==='Received').reduce((s,d)=>s+d.qty,0);
    const rt=RETURNS.filter(r=>r.item===ic&&r.branch===b.code).reduce((s,r)=>s+r.qty,0);
    const dg=ADJUST.filter(a=>a.item===ic&&a.loc===b.code).reduce((s,a)=>s+a.qty,0);
    BR_DMG[ic][b.code]=dg;
    const net=Math.max(0,rec-rt-dg);
    BRANCH_STOCK[ic][b.code]=0;CONSUMED[ic][b.code]=null;
  });
});
const branchTotal=ic=>BR.reduce((s,b)=>s+branchQty(ic,b.code),0);
