  const viewRows=(maxRows>0&&sourceRows.length>maxRows)?sourceRows.slice(0,maxRows):sourceRows;
  const extraClass=opt.compact?' compact-ledger':'';
  let h='<div class="tw'+(opt.cap?' cap':'')+'"><table class="rt'+extraClass+'" id="'+id+'">';
  if(opt.colWidths&&opt.colWidths.length){
    h+='<colgroup>'+opt.colWidths.map(function(w){return '<col style="width:'+w+';min-width:'+w+';max-width:'+w+'">'}).join('')+'</colgroup>';
  }
  h+='<thead><tr>';
  cols.forEach((c,i)=>{h+='<th data-i="'+i+'" class="'+(c.c||'')+'">'+esc(c.t)+'<span class="sarr">▼</span></th>'});
  h+='</tr></thead><tbody>';
  if(!sourceRows.length)h+='<tr><td colspan="'+cols.length+'"><div class="empty"><b>Nothing to show</b>No records match the current filter. Widen the period or clear the search.</div></td></tr>';
  viewRows.forEach(r=>{
    const cl=[r.click?'clickable':'',r.cls||''].filter(Boolean).join(' ');
    h+='<tr'+(cl?' class="'+cl+'"':'')+(r.click?' data-go="'+esc(r.click)+'"':'')+'>';
    r.cells.forEach((c,i)=>{const hv=String(c.h==null?'':c.h);
      h+='<td data-v="'+esc(c.v!=null?c.v:hv.replace(/<[^>]*>/g,''))+'" class="'+(c.c||cols[i].c||'')+'">'+hv+'</td>'});
    h+='</tr>';
  });
  if(sourceRows.length>viewRows.length){h+='<tr class="life-row-limit"><td colspan="'+cols.length+'" style="text-align:center;padding:9px;color:#63806F;font-size:11px">Showing '+viewRows.length+' of '+sourceRows.length+' matching rows for faster filtering</td></tr>';}
  h+='</tbody>';
  if(opt.tot&&sourceRows.length){h+='<tfoot><tr>';opt.tot.forEach((t,i)=>{h+='<td class="'+(cols[i].c||'')+'">'+(t||'')+'</td>'});h+='</tr></tfoot>'}
  return h+'</table></div>';
}
function autoFit(root){
  /* V23 FAST: avoid scanning every cell in large live tables.
     Only inspect a small sample and never loop the full tbody to apply widths. */
  if(!root)return;
  root.querySelectorAll('table.rt').forEach(t=>{
    if(!t.tHead||!t.tHead.rows.length||!t.tBodies.length)return;
    const ths=[...t.tHead.rows[0].cells],rows=[...t.tBodies[0].rows].slice(0,20);
    ths.forEach((th,i)=>{
      if(th.classList.contains('num'))return;
      let mx=th.textContent.length,sum=0,n=0;
      rows.forEach(r=>{const c=r.cells[i];if(!c)return;const L=(c.textContent||'').trim().length;mx=Math.max(mx,L);sum+=L;n++});
      if(mx>30){
        const w=Math.min(260,Math.max(140,Math.round((n?sum/n:20)*6.2)));
        th.style.maxWidth=w+'px';
      }
    });
  });
}
document.addEventListener('click',e=>{
  const th=e.target.closest('table.rt th');if(!th)return;
  const t=th.closest('table'),i=+th.dataset.i,tb=t.tBodies[0];
  const asc=!(th.classList.contains('sorted')&&th.dataset.dir==='asc');
  [...t.tHead.rows[0].cells].forEach(x=>{x.classList.remove('sorted');x.querySelector('.sarr').textContent='▼'});
  th.classList.add('sorted');th.dataset.dir=asc?'asc':'desc';th.querySelector('.sarr').textContent=asc?'▲':'▼';
  const rows=[...tb.rows].filter(r=>r.cells.length>1);
  const isDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(String(s).trim()),isNum=s=>/^-?[0-9][0-9,.\s]*$/.test(String(s).trim());
  rows.sort((a,b)=>{const x=a.cells[i]?a.cells[i].dataset.v:'',y=b.cells[i]?b.cells[i].dataset.v:'';
    let c;if(isDate(x)&&isDate(y))c=String(x).localeCompare(String(y));
    else if(isNum(x)&&isNum(y))c=parseFloat(String(x).replace(/[,\s]/g,''))-parseFloat(String(y).replace(/[,\s]/g,''));
    else c=String(x).localeCompare(String(y),undefined,{numeric:true});return asc?c:-c});
  rows.forEach(r=>tb.appendChild(r));
});
