function fillSelects(){
  $('fBranch').innerHTML='<option value="">HO + all 11 branches</option><option value="HO">HO Central Warehouse only</option>'+
    BR.map(b=>'<option value="'+b.code+'">'+b.name+' ('+b.code+')</option>').join('');
  $('fCat').innerHTML='<option value="">All categories</option>'+CATS.map(c=>'<option>'+c+'</option>').join('');
  $('fType').innerHTML='<option value="">All stock types</option>'+TYPES.map(c=>'<option>'+c+'</option>').join('');
  syncDependent();
  if(!$('fTo').value)$('fTo').value=lifeLocalYMD(TODAY);
  if(!$('fFrom').value)$('fFrom').value=lifeLocalYMD(dAgo(30));
  if($('fPeriod') && !$('fPeriod').dataset.lifeInit){
    $('fPeriod').value='30';
    $('fPeriod').dataset.lifeInit='1';
  }
}
function syncDependent(){
  const cat=$('fCat').value;
  const oldType=$('fType').value;
  const oldVendor=$('fVendor').value;
  const oldItem=$('fItem').value;
  const mv=$('fMove').value;

  /* Category narrows the Stock Type options to types that actually exist
     in the live Item master. Preserve the previous value only when valid. */
  const typeList=TYPES.filter(t=>ITEMS.some(i=>(!cat||i.cat===cat)&&i.type===t));
  $('fType').innerHTML='<option value="">All stock types ('+typeList.length+')</option>'+
    typeList.map(t=>'<option value="'+esc(t)+'"'+(t===oldType?' selected':'')+'>'+esc(t)+'</option>').join('');
  if(oldType && !typeList.includes(oldType))$('fType').value='';
  const typ=$('fType').value;

  /* Supplier list is narrowed by Category + Stock Type.
     Keep only a still-valid supplier selection. */
  const vl=VENDORS.filter(v=>
    (!cat||v.cats.includes(cat))&&
    (!typ||v.types.includes(typ))
  );
  $('fVendor').innerHTML='<option value="">All suppliers ('+vl.length+')</option>'+
    vl.map(v=>{
      const supplierName=String(v.name||v.code||'').trim();
      const supplierCode=String(v.code||'').trim();
      return '<option value="'+esc(supplierCode)+'"'+(vendorEq(supplierCode,oldVendor)?' selected':'')+'>'+esc(supplierName)+'</option>';
    }).join('');
  if(oldVendor && !vl.some(v=>vendorEq(v.code,oldVendor)))$('fVendor').value='';
  const ven=$('fVendor').value;

  /* Stock Item always comes from the complete enabled Item master.
     Other filters only narrow that list; they never invent/remove Item master data. */
  const il=ITEMS.filter(i=>
    (!cat||i.cat===cat)&&
    (!typ||i.type===typ)&&
    (!mv||MOVE[i.code]===mv)&&
    (!ven||(itemVendors[i.code]||[]).some(v=>vendorEq(v,ven)))
  );

  $('fItem').innerHTML='<option value="">All stock items ('+il.length+')</option>'+
    il.map(i=>{
      const itemName=String(i.name||i.code||'').trim();
      const itemCode=String(i.code||'').trim();
      return '<option value="'+esc(itemCode)+'"'+(itemCode===oldItem?' selected':'')+'>'+
        esc(itemName)+(itemCode&&itemCode!==itemName?' — '+esc(itemCode):'')+
      '</option>';
    }).join('');
  if(oldItem && !il.some(i=>i.code===oldItem))$('fItem').value='';
}
function F(){
  const p=$('fPeriod').value;let from=$('fFrom').value,to=$('fTo').value;
  if(p!=='cust'){
    to=lifeLocalYMD(TODAY);
    from=p==='all'?'2000-01-01':lifeLocalYMD(dAgo(+p));
    $('fFrom').value=from;
    $('fTo').value=to;
  }
  return {from,to,branch:$('fBranch').value,cat:$('fCat').value,type:$('fType').value,move:$('fMove').value,
    vendor:$('fVendor').value,item:$('fItem').value,status:$('fStatus').value,pay:$('fPay').value,
    q:$('fSearch').value.trim().toLowerCase()};
}
const venNames=ic=>(itemVendors[ic]||[]).map(v=>VEN(v).name+' '+VEN(v).phone+' '+v).join(' ');
function qMatch(f,parts){if(!f.q)return true;return parts.filter(Boolean).join(' ').toLowerCase().includes(f.q)}
const sameFilterText=(a,b)=>String(a==null?'':a).trim().toLowerCase()===String(b==null?'':b).trim().toLowerCase();
function itemPass(f,ic){const it=ITEM(ic);if(!it)return false;
  if(f.cat&&it.cat!==f.cat)return false;if(f.type&&it.type!==f.type)return false;
  if(f.move&&MOVE[ic]!==f.move)return false;if(f.item&&ic!==f.item)return false;
  if(f.vendor&&!(itemVendors[ic]||[]).some(v=>vendorEq(v,f.vendor)))return false;return true}
const scopeItems=f=>ITEMS.filter(i=>itemPass(f,i.code)).map(i=>i.code);
function fPurch(f){return PURCHASES.filter(p=>p.date>=f.from&&p.date<=f.to&&itemPass(f,p.item)&&
  (!f.vendor||vendorEq(p.vendor,f.vendor))&&(!f.pay||sameFilterText(p.payStatus,f.pay))&&
  qMatch(f,[p.po,p.inv,p.grn,ITEM(p.item).name,p.item,VEN(p.vendor).name,VEN(p.vendor).phone,p.vendor]))}
function fPurchLifetime(f){return LIFETIME_PURCHASES.filter(p=>itemPass(f,p.item)&&
  (!f.vendor||vendorEq(p.vendor,f.vendor))&&
  qMatch(f,[p.po,p.inv,ITEM(p.item)&&ITEM(p.item).name,p.item,VEN(p.vendor)&&VEN(p.vendor).name,VEN(p.vendor)&&VEN(p.vendor).phone,p.vendor]))}
function fDisp(f){return DISPATCH.filter(d=>d.date>=f.from&&d.date<=f.to&&itemPass(f,d.item)&&
  (!f.branch||f.branch===d.branch)&&(!f.status||sameFilterText(d.status,f.status))&&
  qMatch(f,[d.ind,d.challan,ITEM(d.item).name,d.item,bName(d.branch),d.reqBy,venNames(d.item)]))}
function fRet(f){return RETURNS.filter(r=>r.date>=f.from&&r.date<=f.to&&itemPass(f,r.item)&&
  (!f.branch||f.branch===r.branch)&&(!f.status||sameFilterText(r.status,f.status))&&qMatch(f,[r.rid,r.ref,ITEM(r.item).name,r.item,bName(r.branch),r.reason,venNames(r.item)]))}
function fCons(f){return CONSUMPTION.filter(c=>c.date>=f.from&&c.date<=f.to&&itemPass(f,c.item)&&
  (!f.branch||f.branch===c.branch)&&(!f.status||sameFilterText(c.status,f.status))&&qMatch(f,[c.ref,ITEM(c.item).name,c.item,bName(c.branch),c.entry_type,c.client,c.package,venNames(c.item)]))}
function fAdj(f){return ADJUST.filter(a=>a.date>=f.from&&a.date<=f.to&&itemPass(f,a.item)&&
  (!f.branch||f.branch===a.loc)&&(!f.status||!a.status||sameFilterText(a.status,f.status))&&qMatch(f,[a.aid,ITEM(a.item).name,a.item,bName(a.loc),a.reason,venNames(a.item)]))}
function fCmp(f){return COMPLAINTS.filter(c=>c.date>=f.from&&c.date<=f.to&&itemPass(f,c.item)&&
  (!f.vendor||c.vendor===f.vendor)&&(!f.branch||f.branch===c.branch)&&
  qMatch(f,[c.cid,ITEM(c.item).name,VEN(c.vendor).name,c.type,bName(c.branch)]))}

