function forecast(ic){
  const it=ITEM(ic),lr=lastRate(ic);
  const open=bookedOpen(ic),thisM=bookedMonth(ic,THIS_M),lastM=bookedMonth(ic,LAST_M);
  const last3=BOOKINGS.filter(b=>b.item===ic).slice(-3);
  const avg=last3.length?Math.round(last3.reduce((s,b)=>s+b.qty,0)/last3.length):0;
  const ho=HO_STOCK[ic],br=branchTotal(ic),avail=ho+br;
  const req=Math.round(Math.max(thisM,avg)*3+open+it.rl); /* one quarter cover + open bookings + reorder buffer */
  const diff=req-avail;
  let pr='Not needed',prN=0;
  if(diff>0){if(MOVE[ic]==='H'||ho<=it.rl){pr='Urgent';prN=3}else if(MOVE[ic]==='M'){pr='High';prN=2}else{pr='Medium';prN=1}}
  return {open,thisM,lastM,avg,ho,br,avail,req,diff,pr,prN,worth:Math.max(0,diff)*lr,rate:lr}
}
