function detect(q){
  q=(q||'').trim().toLowerCase();if(!q)return [];
  const out=[],digits=q.replace(/\D/g,'');
  if(digits.length>=5)VENDORS.forEach(v=>{if(v.phone.includes(digits)||v.alt.replace(/\D/g,'').includes(digits)||v.rmPhone.includes(digits))
    out.push({k:'vendor',c:v.code,l:v.name,w:'phone '+v.phone})});
  ITEMS.forEach(i=>{if(i.code.toLowerCase().includes(q))out.push({k:'item',c:i.code,l:i.name,w:'product code '+i.code});
    else if(i.name.toLowerCase().includes(q))out.push({k:'item',c:i.code,l:i.name,w:i.cat+' · '+i.type})});
  VENDORS.forEach(v=>{if(v.name.toLowerCase().includes(q)||v.code.toLowerCase().includes(q))
    out.push({k:'vendor',c:v.code,l:v.name,w:v.level+' · '+v.city})});
  DISPATCH.forEach(d=>{if(String(d.ind||'').toLowerCase()===q||String(d.challan||d.ref||'').toLowerCase()===q)
    out.push({k:'item',c:d.item,l:ITEM(d.item).name,w:'indent '+d.ind+' → '+bName(d.branch)})});
  PURCHASES.forEach(p=>{if(p.inv.toLowerCase()===q||p.po.toLowerCase()===q)
    out.push({k:'vendor',c:p.vendor,l:VEN(p.vendor).name,w:'invoice '+p.inv})});
  const seen=new Set();
  return out.filter(o=>{const k=o.k+o.c+o.w;if(seen.has(k))return false;seen.add(k);return true}).slice(0,12);
}
