const ITEM_HISTORY_CACHE={};
const ITEM_HISTORY_LOADING={};

function itemHistoryUrl(ic){
  const qs=new URLSearchParams();
  qs.set('item_code',ic);
  qs.set('action','item_history');
  qs.set('_stores360_version','V25.37');
  qs.set('_ts',String(Date.now()));
  return '/api/method/life_stores_360_live_api?'+qs.toString();
}

async function loadItemHistory(ic){
  if(ITEM_HISTORY_CACHE[ic]){
    return ITEM_HISTORY_CACHE[ic];
  }

  if(ITEM_HISTORY_LOADING[ic]){
    return ITEM_HISTORY_LOADING[ic];
  }

  ITEM_HISTORY_LOADING[ic]=(async function(){
    const controller=new AbortController();
    const timer=setTimeout(function(){
      controller.abort();
    },15000);

    try{
      const response=await fetch(
        itemHistoryUrl(ic),
        {
          method:'GET',
          credentials:'same-origin',
          headers:{'Accept':'application/json'},
          signal:controller.signal
        }
      );

      const text=await response.text();
      let payload={};

      try{
        payload=text?JSON.parse(text):{};
      }catch(parseError){
        throw new Error(
          'Item history API returned invalid JSON.'
        );
      }

      if(!response.ok){
        throw new Error(
          'Item history API HTTP '+response.status+
          (payload&&payload.exception
            ?' · '+payload.exception
            :'')
        );
      }

      const d=(
        payload &&
        payload.message!==undefined
      )
        ?payload.message
        :payload;

      if(!d || d.ok===false){
        throw new Error(
          (d&&d.message)
            ?d.message
            :'Item history could not be loaded.'
        );
      }

      ITEM_HISTORY_CACHE[ic]={
        purchases:(Array.isArray(d.purchases)?d.purchases:[]).map(function(p){
          return Object.assign({},p,{vendor:vendorCode(p.vendor||p.vendor_name||''),qty:nval(p.qty),rate:nval(p.rate),val:nval(p.val||p.amount)});
        }),
        dispatch:(Array.isArray(d.dispatch)?d.dispatch:[]).map(function(x){
          return Object.assign({},x,{branch:brCode(x.branch||x.target||x.target_warehouse),qty:nval(x.qty),rate:nval(x.rate),val:nval(x.val)});
        }),
        returns:(Array.isArray(d.returns)?d.returns:[]).map(function(x){
          return Object.assign({},x,{branch:brCode(x.branch||x.source||x.source_warehouse),qty:nval(x.qty),rate:nval(x.rate),val:nval(x.val)});
        }),
        consumption:(Array.isArray(d.consumption)?d.consumption:[]).map(function(x){
          return Object.assign({},x,{branch:brCode(x.branch||x.source||x.source_warehouse),qty:nval(x.qty),rate:nval(x.rate),val:nval(x.val)});
        }),
        adjust:(Array.isArray(d.adjust)?d.adjust:[]).map(function(x){
          return Object.assign({},x,{loc:brCode(x.loc||x.target_warehouse)||String(x.loc||''),qty:nval(x.qty),rate:nval(x.rate),val:nval(x.val)});
        })
      };

      return ITEM_HISTORY_CACHE[ic];

    }finally{
      clearTimeout(timer);
      delete ITEM_HISTORY_LOADING[ic];
    }
  })();

  return ITEM_HISTORY_LOADING[ic];
}

function itemHistoryData(ic){
  return ITEM_HISTORY_CACHE[ic]||{
    purchases:PURCHASES.filter(
