const CART=[];
function bestVendor(ic){
  const mapped=(itemVendors[ic]||[]).map(VEN).filter(v=>v&&v.code&&!v.blocked);
  return mapped.sort((a,b)=>Number(b.rating||0)-Number(a.rating||0))[0]||{code:'',name:'',level:'',rating:0,blocked:false};
}
function suggestQty(ic){const f=forecast(ic);return Math.max(1,f.diff>0?f.diff:0,Number(ITEM(ic).rl||0))}
function modal(title,body,btns,warn){
  $('modalT').textContent=title;$('modalB').innerHTML=body;
  $('modal').style.borderTopColor=warn?'#8E6408':'#2C7A50';
  $('modalF').innerHTML='';
  btns.forEach(b=>{const el=document.createElement('button');el.className='btn '+(b.cls||'');el.textContent=b.label;
    el.onclick=()=>{closeModal();b.fn&&b.fn()};$('modalF').appendChild(el)});
