}
function closeModal(){$('modal').classList.remove('on');if(!$('cartDrawer').classList.contains('on'))$('backdrop').classList.remove('on')}
function addToCart(ic,qty){
  const it=ITEM(ic),q=Math.max(1,Number(qty&&qty>0?qty:suggestQty(ic))||1);
  const ex=CART.find(c=>c.item===ic);
  if(ex){
    modal('Already in the next order list',
      '<b class="nm">'+esc(it.name)+'</b> '+altTag(ic)+'<br>It is already parked with <b>'+num(ex.qty)+' '+it.unit+
      '</b> (added '+ex.added+', vendor '+esc(ex.vendor)+').<br><br>Do you want to add <b>'+num(q)+'</b> more, replace the quantity, or leave it as it is?',
      [{label:'Cancel',cls:''},
       {label:'Replace with '+num(q),cls:'gold',fn:()=>{ex.qty=q;ex.worth=q*ex.rate;renderCart();toast('Quantity replaced')}},
       {label:'Add '+num(q)+' more',cls:'primary',fn:()=>{ex.qty+=q;ex.worth=ex.qty*ex.rate;renderCart();toast('Quantity increased')}}],true);
    return;
  }
  const v=bestVendor(ic),rate=lastRate(ic),f=forecast(ic);
  CART.push({item:ic,name:it.name,unit:it.unit,cat:it.cat,type:it.type,qty:q,rate,worth:q*rate,
    vendor:v.name,vendorCode:v.code,level:v.level,priority:f.pr==='Not needed'?'Medium':f.pr,
    added:dmy(iso(TODAY)),move:MOVE[ic]});
  renderCart();toast(it.name+' added to the next order list');
}

