let LIFE_CREATED_DRAFT_POS=[];

function lifeCsrf(){
  return (window.frappe&&frappe.csrf_token)?frappe.csrf_token:'';
}

async function lifeGetPurchaseOrder(name){
  const u='/api/method/frappe.client.get?doctype='+encodeURIComponent('Purchase Order')+'&name='+encodeURIComponent(name);
  const r=await fetch(u,{method:'GET',credentials:'same-origin',headers:{'Accept':'application/json','X-Frappe-CSRF-Token':lifeCsrf()}});
  const raw=await r.text();
  let p={};try{p=raw?JSON.parse(raw):{};}catch(_){throw new Error('Invalid Purchase Order response');}
  if(!r.ok)throw new Error(p.exception||p.exc_type||('HTTP '+r.status));
  return p.message||p;
}

async function lifeGetWorkflowTransitions(doc){
  try{
    const fd=new URLSearchParams();
    fd.set('doc',JSON.stringify(doc));
    const r=await fetch('/api/method/frappe.model.workflow.get_transitions',{
      method:'POST',credentials:'same-origin',
      headers:{'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Frappe-CSRF-Token':lifeCsrf()},
      body:fd.toString()
    });
    const raw=await r.text();
    let p={};try{p=raw?JSON.parse(raw):{};}catch(_){return [];}
    if(!r.ok)return [];
    return Array.isArray(p.message)?p.message:[];
  }catch(_){return [];}
}

function lifeApprovalActionFromTransitions(ts){
  if(!Array.isArray(ts))return 'Send for Approval';
  const actions=ts.map(x=>String((x&&x.action)||'').trim()).filter(Boolean);
  return actions.find(a=>/send.*approval|submit.*approval|request.*approval/i.test(a))
      || actions.find(a=>/approval/i.test(a))
      || 'Send for Approval';
}

async function lifeApplyPoWorkflow(name,action){
  const doc=await lifeGetPurchaseOrder(name);
  const fd=new URLSearchParams();
  fd.set('doc',JSON.stringify(doc));
  fd.set('action',action);
  const r=await fetch('/api/method/frappe.model.workflow.apply_workflow',{
    method:'POST',credentials:'same-origin',
    headers:{'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Frappe-CSRF-Token':lifeCsrf()},
    body:fd.toString()
  });
  const raw=await r.text();
  let p={};try{p=raw?JSON.parse(raw):{};}catch(_){throw new Error('Invalid workflow response');}
  if(!r.ok){
    let msg=p.exception||p.exc_type||('HTTP '+r.status);
    if(p._server_messages){try{const a=JSON.parse(p._server_messages);msg=(a||[]).map(x=>{try{const o=typeof x==='string'?JSON.parse(x):x;return o.message||o.msg||String(x)}catch(_){return String(x)}}).filter(Boolean).join(' · ')||msg}catch(_){}}
    throw new Error(msg);
  }
  return p.message||{};
}

async function lifeRefreshDraftApprovalMeta(){
  for(const x of LIFE_CREATED_DRAFT_POS){
    try{
      const doc=await lifeGetPurchaseOrder(x.name);
      x.workflow_state=doc.workflow_state||'';
      x.status=doc.status||'';
      x.docstatus=Number(doc.docstatus||0);
      x.grand_total=Number(doc.grand_total||x.grand_total||0);
      const ts=await lifeGetWorkflowTransitions(doc);
      x.transitions=ts;
      x.send_action=lifeApprovalActionFromTransitions(ts);
    }catch(e){
      x.load_error=String((e&&e.message)||e||'');
    }
  }
}

