    if(subEl)subEl.textContent=LIFE_CREATED_DRAFT_POS.length+' Draft PO'+(LIFE_CREATED_DRAFT_POS.length>1?'s':'')+' ready for approval';
    if(btn){
      const need=LIFE_CREATED_DRAFT_POS.filter(x=>{
        const st=String(x.workflow_state||x.status||'');
        return !/pending|approved|rejected|cancelled/i.test(st);
