async function createRealPurchaseOrders(){
  if(!CART.length){toast('Add items before creating PO');return;}
  const badQty=CART.find(c=>Number(c.qty||0)<=0);
  if(badQty){modal('Order quantity required','Set Order Qty greater than zero for <b>'+esc(badQty.name||badQty.item)+'</b>.',[{label:'Close'}],true);return;}
  const missingSupplier=CART.find(c=>!String(c.vendorCode||'').trim());
  if(missingSupplier){modal('Supplier required','Select a supplier in Next Order List for <b>'+esc(missingSupplier.name||missingSupplier.item)+'</b> before creating the Purchase Order.',[{label:'Close'}],true);return;}

  const btn=$('cartConfirm');
  const oldText=btn?btn.textContent:'';
  if(btn){btn.disabled=true;btn.textContent='Creating Draft PO...';}

  try{
    const fd=new URLSearchParams();
    fd.set('action','create_purchase_orders');
    /* V25.13 SAFE_EXEC: do not send JSON. Frappe Server Script safe_exec on this site
       does not expose frappe.parse_json, so send indexed form fields instead. */
    fd.set('cart_count',String(CART.length));
    CART.forEach((c,i)=>{
      fd.set('cart_'+i+'_item',String(c.item||''));
      fd.set('cart_'+i+'_item_name',String(c.name||''));
      fd.set('cart_'+i+'_qty',String(Number(c.qty||0)));
      fd.set('cart_'+i+'_rate',String(Number(c.rate||0)));
      fd.set('cart_'+i+'_supplier',String(c.vendorCode||c.vendor||''));
      fd.set('cart_'+i+'_priority',String(c.priority||''));
    });

    const response=await fetch('/api/method/life_stores_360_live_api',{
      method:'POST',
      credentials:'same-origin',
      headers:{
        'Accept':'application/json',
        'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8',
        'X-Frappe-CSRF-Token':(window.frappe&&frappe.csrf_token)?frappe.csrf_token:''
      },
      body:fd.toString()
    });

    const raw=await response.text();
    let payload={};
    try{payload=raw?JSON.parse(raw):{};}catch(e){throw new Error('Invalid server response while creating Purchase Order.');}

    if(!response.ok){
      let serverMsg='';
      if(payload&&payload._server_messages){
        try{
          const sm=JSON.parse(payload._server_messages);
          serverMsg=(Array.isArray(sm)?sm:[]).map(x=>{
            try{const o=typeof x==='string'?JSON.parse(x):x;return o.message||o.msg||String(x)}catch(_){return String(x)}
          }).filter(Boolean).join(' · ');
        }catch(_){serverMsg=String(payload._server_messages||'')}
      }
      throw new Error(serverMsg||payload.exception||payload.exc_type||('HTTP '+response.status));
    }

    const data=payload.message||{};
    if(!data.ok){throw new Error(data.message||'Purchase Order creation failed.');}

    const made=Array.isArray(data.created)?data.created:[];
    const links=made.map(x=>
      '<div style="padding:8px 0;border-bottom:1px solid #E5EFE8">'+
      '<a class="nm" target="_blank" href="/app/purchase-order/'+encodeURIComponent(x.name)+'">'+esc(x.name)+'</a>'+
      ' <span class="sub2">· '+esc(x.supplier||'')+' · '+Number(x.item_count||0)+' item(s) · Draft</span>'+ 
      (Number(x.grand_total||0)>0?' <b class="money">'+money(Number(x.grand_total||0))+'</b>':'')+
      '</div>'
    ).join('');

    LIFE_CREATED_DRAFT_POS.splice(0,LIFE_CREATED_DRAFT_POS.length,...made.map(x=>Object.assign({},x)));
    CART.length=0;
    await lifeRefreshDraftApprovalMeta();
    renderCart();
    openCart(true);
    lifeRenderApprovalCards();
    lifeSyncApprovalFooter();
    toast(made.length+' Draft PO created · ready for approval');
  }catch(err){
    console.error('[Stores 360] Create PO failed',err);
    const msg=String((err&&err.message)||err||'Unable to create Purchase Order');
    modal('Could not create Purchase Order','<div class="tag bad" style="white-space:normal;line-height:1.5">'+esc(msg)+'</div><div class="sub2" style="margin-top:10px">Your order list is preserved. Close this message, correct the shown issue if any, and try again.</div>',[{label:'Close',fn:()=>openCart(true)}],true);
  }finally{
    if(btn){btn.disabled=false;btn.textContent=oldText||'Create Draft PO';}
  }
}

