$('cartConfirm').onclick=async()=>{
  /* After Draft PO creation, the same bottom button becomes Send for Approval. */
  if(LIFE_CREATED_DRAFT_POS.length){
    const btn=$('cartConfirm');
    const pending=LIFE_CREATED_DRAFT_POS.filter(x=>{
      const st=String(x.workflow_state||x.status||'');
      return !/pending|approved|rejected|cancelled/i.test(st);
    });
    if(!pending.length){toast('Approval has already been sent');lifeSyncApprovalFooter();return;}

    const oldText=btn?btn.textContent:'';
    if(btn){btn.disabled=true;btn.textContent='Sending for Approval...';}
    try{
      for(const x of pending){
        const doc=await lifeGetPurchaseOrder(x.name);
        const ts=await lifeGetWorkflowTransitions(doc);
        const action=lifeApprovalActionFromTransitions(ts);
        await lifeApplyPoWorkflow(x.name,action);
      }
      await lifeRefreshDraftApprovalMeta();
      lifeRenderApprovalCards();
      lifeSyncApprovalFooter();
      toast('Purchase Order sent for approval');
    }catch(err){
      console.error('[Stores 360] Send PO for approval failed',err);
      const msg=String((err&&err.message)||err||'Unable to send Purchase Order for approval');
      modal('Could not send for approval','<div class="tag bad" style="white-space:normal;line-height:1.5">'+esc(msg)+'</div><div class="sub2" style="margin-top:10px">The Draft PO is still saved. Nothing was deleted.</div>',[{label:'Close',fn:()=>openCart(true)}],true);
    }finally{
      if(btn && !btn.disabled){btn.textContent=oldText||'Send for Approval';}
      lifeSyncApprovalFooter();
    }
    return;
  }

  if(!CART.length)return toast('Add items before creating PO');

  CART.forEach(c=>{
    if(String(c.vendorCode||'').trim())return;
    const mapped=(itemVendors[c.item]||[]).map(code=>VEN(code)).find(v=>v&&v.code&&!v.blocked);
    if(mapped){
      c.vendorCode=mapped.code;
      c.vendor=mapped.name||mapped.code;
      c.level=mapped.level||'';
    }
  });

  const badQty=CART.find(c=>Number(c.qty||0)<=0);
  if(badQty){
    return modal('Order quantity required','Set Order Qty greater than zero for <b>'+esc(badQty.name||badQty.item)+'</b>.',[{label:'Close',fn:()=>openCart(true)}],true);
  }
  const missingSupplier=CART.find(c=>!String(c.vendorCode||'').trim());
  if(missingSupplier){
    renderCart();
    return modal('Supplier required','Select a supplier for <b>'+esc(missingSupplier.name||missingSupplier.item)+'</b> in Next Order List, then click Create Draft PO again.',[{label:'Back to Order List',cls:'primary',fn:()=>openCart(true)}],true);
  }

  await createRealPurchaseOrders();
};
