  return '<option value="">All Branches (11)</option>'+
    '<optgroup label="Clusters">'+clusterOptions+'</optgroup>'+
    '<optgroup label="Individual Branches">'+branchOptions+'</optgroup>';
}
function catOptsHtml(){return '<option value="">All categories</option>'+CATS.map(c=>'<option>'+esc(c)+'</option>').join('')}
const stOpts='<option value="">Mt + Con + Adv</option>'+Object.keys(STY).map(k=>'<option value="'+k+'">'+STY[k].b+' — '+STY[k].n+'</option>').join('');
