function syncTreat(){const cat=$('srcCat').value,cur=$('srcTreat').value;
  const source=Array.isArray(TREAT)?TREAT:[];
  const l=source.filter(t=>t&&(!cat||t.cat===cat));
  $('srcTreat').innerHTML='<option value="">All treatments ('+l.length+')</option>'+l.map(t=>'<option'+(t.n===cur?' selected':'')+'>'+esc(t.n)+'</option>').join('')}
function syncBy(w){
  const id=w==='c'?'srcBy':'srsBy';
  const brEl=$(w==='c'?'srcBr':'srsBr');
  const selEl=$(id);
  const br=brEl?String(brEl.value||''):'';
  const cur=selEl?String(selEl.value||''):'';
  const src=w==='c'?CSTK:SREQ;
  const m=new Map();

  (Array.isArray(src)?src:[]).forEach(function(x){
    x=x||{};
    if(!brPass(br,x.br))return;

    const rb=(x.reqBy&&typeof x.reqBy==='object')?x.reqBy:{};
    const name=String(
      rb.n||
      x.requestByName||
      x.request_by_name||
      x.reqByName||
      x.requestBy||
      x.owner||
      ''
    ).trim();
    const role=String(
      rb.r||
      x.requestByRole||
      x.request_by_role||
      x.reqByRole||
      x.role||
      ''
    ).trim();

    if(!name)return;
    if(!m.has(name) || (!m.get(name) && role))m.set(name,role);
  });

  const l=[...m.entries()].sort(function(a,b){
    return String(a&&a[0]||'').localeCompare(
      String(b&&b[0]||''),
      undefined,
      {numeric:true,sensitivity:'base'}
    );
  });

  if(!selEl)return;

  selEl.innerHTML='<option value="">Everyone ('+l.length+')</option>'+
    l.map(function(e){
      const name=String(e&&e[0]||'');
      const role=String(e&&e[1]||'');
      return '<option value="'+esc(name)+'"'+(name===cur?' selected':'')+'>'+
        esc(name)+(role?' — '+esc(role):'')+'</option>';
    }).join('');
}
