/* ---------- filters ---------- */
function cF(){return {from:$('srcFrom').value||'2000-01-01',to:$('srcTo').value||'2999-12-31',br:$('srcBr').value,cat:$('srcCat').value,
  treat:$('srcTreat').value,st:$('srcSt').value,exec:$('srcExec').value,by:$('srcBy').value,q:$('srcQ').value.trim().toLowerCase(),
  item:$('srcItem').value.trim().toLowerCase(),pend:$('srcPend').checked,age:+($('srcAge').value||0)}}
function sF(){return {from:$('srsFrom').value||'2000-01-01',to:$('srsTo').value||'2999-12-31',br:$('srsBr').value,cat:$('srsCat').value,
  st:$('srsSt').value,stat:$('srsStat').value,gf:$('srsGf').value,diff:$('srsDiff').value,by:$('srsBy').value,q:$('srsItem').value.trim().toLowerCase()}}
function clientMatch(c,q){if(!q)return true;const d=q.replace(/\D/g,'');
  if(d.length>=4&&/^[\d\s-]+$/.test(q))return c.mob.endsWith(d)||c.mob.includes(d)||c.id.includes(d);
  return c.name.toLowerCase().includes(q)||c.id.toLowerCase().includes(q)}
function cFilter(f,ignoreCat){return CSTK.filter(x=>{
  if(x.reqDate<f.from||x.reqDate>f.to)return false;
  if(!brPass(f.br,x.br))return false;
  if(!ignoreCat&&f.cat&&x.cat!==f.cat)return false;
  if(f.treat&&x.treat!==f.treat)return false;
  if(f.st&&x.st!==f.st)return false;
  if(f.exec&&x.flag!==f.exec)return false;
  if(f.pend&&x.pend<=0)return false;
  if(f.age&&!(x.pend>0&&x.pAge>f.age))return false;
  if(f.by&&!sameFilterText(
    (x.reqBy&&x.reqBy.n)||
    x.requestByName||
    x.request_by_name||
    x.reqByName||
    x.requestBy||
    '',
    f.by
  ))return false;
  if(!x.cl)return false;
  if(S.cSel){if(x.cl.id!==S.cSel)return false}else if(!clientMatch(x.cl,f.q))return false;
  if(f.item){
    const it=ITEM(x.item)||{name:String(x.item||''),code:String(x.item||'')};
    if(!(String(it.name||'').toLowerCase().includes(f.item)||String(it.code||'').toLowerCase().includes(f.item)))return false
  }
  return true})}
function sFilter(f,ignoreCat){return SREQ.filter(x=>{
  if(x.reqDate<f.from||x.reqDate>f.to)return false;
  if(!brPass(f.br,x.br))return false;
  if(!ignoreCat&&f.cat&&x.cat!==f.cat)return false;
  if(f.st&&x.st!==f.st)return false;
  if(f.stat&&x.status!==f.stat)return false;
  if(f.gf==='HO'&&x.from!=='HO')return false;
  if(f.gf==='BR'&&(!x.from||x.from==='HO'))return false;
  if(f.diff==='ok'&&!(x.rec&&Number(x.diff||0)===0))return false;
  if(f.diff==='bad'&&!(x.rec&&Number(x.diff||0)>0))return false;
  if(f.by&&!sameFilterText(
    (x.reqBy&&x.reqBy.n)||
    x.requestByName||
    x.request_by_name||
    x.reqByName||
    x.requestBy||
    '',
    f.by
  ))return false;
  if(f.q){
    const it=ITEM(x.item)||{name:String(x.item||''),code:String(x.item||'')};
    const hay=[
      it.name,it.code,x.id,
      x.cl?x.cl.name:'',x.cl?x.cl.id:'',
      x.treat,bName(x.br),
      x.reqBy&&x.reqBy.n?x.reqBy.n:'',
      x.reqBy&&x.reqBy.r?x.reqBy.r:'',
      x.from||'',x.status||''
    ].join(' ').toLowerCase();
    if(!hay.includes(f.q))return false
  }
  return true})}

