    brMini(x.br).replace('brm','brm big')+'<span class="x2 rb">'+esc(x.reqBy.n)+'</span><span class="x2">'+x.reqBy.r+'</span>',
    '<span class="it1"'+(P?'':' data-item="'+x.item+'" title="Open Indent 360"')+'>'+esc(it.name)+'</span> '+stBadge(x.st)+
      '<span class="x2">'+catPill(x.cat)+' <span class="mono">'+it.code+'</span> · '+it.unit+'</span>'+
      (x.cl?'<span class="x2 fc"'+(P?'':' data-lock="'+x.cl.id+'" title="Open client statement"')+'>For '+esc(x.cl.name)+' ('+x.cl.id+') · '+esc(x.treat)+'</span>':'<span class="x2 bm">Branch monthly indent</span>'),
    '<b>'+x.reqQty+'</b>',
    dmy(x.reqDate)+'<span class="x2 mono">'+x.id+'</span>',
    sBadge(x.status)+'<span class="x2">'+(x.reason?esc(x.reason):(x.apBy?'by '+x.apBy:'Awaiting HO action'))+'</span>',
    (!approvedKnown||x.status==='Pending')?dash:'<span class="aq">'+x.apr+'</span> / <span class="rq'+(x.rej?'':' z')+'">'+x.rej+'</span>',
    !x.from?dash:(x.from==='HO'?'<span class="gf ho">HO</span><span class="x2 gs">Central Warehouse</span>':'<span class="gf br">Br</span>'+brMini(x.from)+'<span class="x2">Branch transfer</span>'),
    x.recDate?dmy(x.recDate)+'<span class="x2">TAT '+x.tat+' d</span>':(x.transit?'<span class="tag info">In transit</span>':dash),
    x.adj?'<span class="aj">'+x.adj+'</span><span class="x2">'+esc(x.adjR)+'</span>':dash,
    x.rec?'<b>'+x.bal+'</b>':dash,
    x.rec?'<b>'+x.rec+'</b>'+(approvedKnown&&x.rec<x.apr?'<span class="x2" style="color:#A63A28">short '+(x.apr-x.rec)+'</span>':''):dash,
    x.rec?String(x.etd):dash,
    x.rec?(x.diff?'<span class="df bad">'+x.diff+'</span><span class="x2" style="color:#A63A28">unaccounted</span>':'<span class="df ok">0 ✓</span>'):dash];
}
function sTotals(rows){
  const approvedKnown=rows.filter(x=>x.apr!==null&&x.apr!==undefined);
  const executedKnown=rows.filter(x=>x.etd!==null&&x.etd!==undefined);
  const balanceKnown=rows.filter(x=>x.bal!==null&&x.bal!==undefined);
  const diffKnown=rows.filter(x=>x.diff!==null&&x.diff!==undefined);

  const uniquePhysical={};
  rows.forEach(function(x){
    if(
      x.br &&
      x.item &&
      x.currentBranchStock!==null &&
      x.currentBranchStock!==undefined
    ){
      uniquePhysical[x.br+'||'+x.item]=Number(x.currentBranchStock)||0;
    }
  });

  const physicalBalance=Object.keys(uniquePhysical)
    .reduce(function(total,key){
      return total+uniquePhysical[key];
    },0);

  return{
    n:rows.length,
    br:new Set(rows.map(x=>x.br).filter(Boolean)).size,
    req:sumBy(rows,x=>x.reqQty),
    apr:sumBy(approvedKnown,x=>x.apr),
    aprKnown:approvedKnown.length,
    rej:sumBy(rows,x=>x.rej),
    rejN:rows.filter(x=>/reject/i.test(x.status)).length,
    pendN:rows.filter(x=>/pending/i.test(x.status)).length,
    b2b:rows.filter(x=>x.st==='MT').length,
    tr:rows.filter(x=>x.transit).length,
    etd:sumBy(executedKnown,x=>x.etd),
    etdKnown:executedKnown.length,
    adj:sumBy(rows,x=>x.adj),
    bal:sumBy(balanceKnown,x=>x.bal),
    balKnown:balanceKnown.length,
    physicalBal:physicalBalance,
    diff:sumBy(diffKnown,x=>x.diff),
    diffKnown:diffKnown.length,
    diffN:diffKnown.filter(x=>Number(x.diff)>0).length,
    rec:sumBy(rows,x=>x.rec),
    tat:(a=>{
      return a.length
        ?(a.reduce((p,q)=>p+q,0)/a.length).toFixed(1)
        :'—'
    })(rows.filter(x=>x.recAg!=null).map(x=>x.recAg))
  };
}
function sTable(rows,P){
  if(!rows.length)return '<div class="sr-empty"><b>No stock requests for this filter</b>Widen the period or reset the status / diff filters.</div>';
  const T=sTotals(rows);let h='<div class="sr-tw"><table class="srt" data-t="s">'+thead(SCOLS,S.sSort,P)+'<tbody>';
  rows.forEach(x=>{h+='<tr class="k-'+CK[x.cat]+(x.status==='Rejected'?' rj':'')+'">'+sCells(x,P).map((v,i)=>'<td class="'+(SCOLS[i].c||'')+'">'+v+'</td>').join('')+'</tr>'});
  h+='</tbody><tfoot><tr><td>TOTAL — '+T.br+' branches</td><td>'+T.n+' requests</td><td class="n">'+num(T.req)+'</td><td></td><td>Rej '+T.rejN+' · Pend '+T.pendN+'</td>'+
    '<td class="ctr"><span class="aq">'+(T.aprKnown?num(T.apr):'—')+'</span> / <span class="rq">'+num(T.rej)+'</span></td><td>B2B '+T.b2b+'</td><td>'+T.tr+' in transit</td><td>'+num(T.adj)+'</td>'+
    '<td class="n">'+(T.balKnown?num(T.bal):'—')+'</td><td class="n">'+num(T.rec)+'</td><td class="n">'+(T.etdKnown?num(T.etd):'—')+'</td><td class="n">'+(T.diff?'<span class="df bad">'+T.diff+'</span>':'0')+'</td></tr></tfoot>';
  return h+'</table></div>';
}
function sKpis(rows){
  const T=sTotals(rows);
  const ap=T.req?Math.round(T.apr/T.req*100):0;

  return '<div class="sr-kpis">'+
    kp('','Requests',T.n,T.br+' branches · '+T.b2b+' branch transfers')+
    kp('','Requested qty',num(T.req),'Material Request Item.qty')+
    kp(
      'g',
      'Approved qty',
      T.aprKnown?num(T.apr):'—',
      T.aprKnown
        ?ap+'% of requested · custom_approved_qty'
        :'Exact approved quantity not stored on these rows'
    )+
    kp('r','Rejected qty',num(T.rej),T.rejN+' requests rejected')+
    kp('m','Pending approval',T.pendN,'awaiting HO action')+
    kp(
      't',
      'Received in branch',
      num(T.rec),
      T.tr+' in transit · confirmed receipt qty'
    )+
    kp(
      'g',
      'Executed qty',
      T.etdKnown?num(T.etd):'—',
      T.etdKnown
        ?'exact consumed quantity'
        :'ERP has session evidence, not item-consumption quantity'
    )+
    kp(
      'o',
      'Current stock in branch',
      num(T.physicalBal),
      'live ERP branch warehouse balance · unique item/branch'
    )+
    kp(
      T.diff?'r':'g',
      'Diff (unaccounted)',
      T.diffKnown?num(T.diff):'—',
      T.diffKnown
        ?T.diffN+' confirmed receipt lines to explain'
        :'shown only after receipt reconciliation'
    )+
  '</div>';
}
