/* ---------- LIVE ERP payload adapter ---------- */

function lifeSRBrCode(v){
  const s=String(v||'').toLowerCase().trim();
  if(!s)return '';
  if(s==='bh'||s.includes('banjara'))return 'BH';
  if(s==='dsk'||s==='dn'||s.includes('dilsukh'))return 'DSK';
  if(s==='hn'||s.includes('himayat')||s.includes('himayath'))return 'HN';
  if(s==='kp'||s.includes('kukat'))return 'KP';
  if(s==='mp'||s.includes('madhapur'))return 'MP';
  if(s==='vz'||s.includes('vizag')||s.includes('visakh'))return 'VZ';
  if(s==='vja'||s==='vw'||s.includes('vijayawada'))return 'VJA';
  if(s==='srn'||s.includes('sr nagar')||s.includes('s r nagar'))return 'SRN';
  if(s==='chn'||s==='cn'||s.includes('chandan'))return 'CHN';
  if(s==='nlr'||s.includes('nellore'))return 'NLR';
  if(s==='gcb'||s==='gb'||s.includes('gachibowli'))return 'GCB';
  if(s==='ho'||s.includes('head office')||s.includes('stores -')||s.includes('central warehouse'))return 'HO';
  return '';
}

function realBranchItemBalanceFromPayload(d,itemCode,branchCode){
  const all=d&&d.branch_stock&&d.branch_stock[itemCode];
  if(!all || typeof all!=='object')return null;

  let total=0;
  let found=false;

  Object.keys(all).forEach(function(warehouse){
    const bc=lifeSRBrCode(warehouse);
    if(bc===branchCode){
      total+=Number(all[warehouse]||0);
      found=true;
    }
  });

  return found?total:null;
}

window.LIFE_SR_APPLY_LIVE=function(d){
  d=d||{};
  const rows=(d.stock_requests||[]).slice();
  const clientRows=(d.clients||[]).slice();
  const itemRows=(d.items||[]).slice();
  const dispatchRows=(d.dispatch||[]).slice();
  const brCode=lifeSRBrCode;

  console.info('[LIFE Stores 360 Reports payload]',{
    stock_requests:rows.length,
    clients:clientRows.length,
    items:itemRows.length,
    dispatch:dispatchRows.length
  });
  const catOf=function(v){
    const s=String(v||'').toLowerCase();
    if(s.includes('slim')||s.includes('weight'))return 'Slimming';
    /* Hair Transplant stays as HT. Skin / Hair Treatment / Laser / Dermatology roll up to Dermat. */
    if(s==='ht'||s.includes('hair transplant')||s.includes('(ht)'))return 'HT';
    if(s.includes('dermat')||s.includes('skin')||s.includes('laser')||s.includes('hair'))return 'Dermat';
    if(s.includes('cool')||s.includes('cryo'))return 'Cools';
    if(s.includes('life rise')||s.includes('nutrition')||s.includes('rise'))return 'Life Rise';
    if(s.includes('sale')||s.includes('retail')||s.includes('product'))return 'Sale Product';
    return 'Sale Product';
  };
  const stOf=function(v,client){
    const s=String(v||'').toLowerCase();
    if(s.includes('advance')||s==='adv')return 'Adv';
    if(s.includes('consum')||s.includes('special')||s==='con')return 'Con';
    if(s.includes('monthly')||s.includes('general')||s.includes('station')||s==='mt')return 'Mt';
    return client?'Con':'Mt';
  };
  const daysAgo=function(v){
    if(!v)return 0;
    const dt=new Date(v);
    if(isNaN(dt.getTime()))return 0;
    return Math.max(0,Math.floor((new Date().setHours(0,0,0,0)-new Date(dt.getFullYear(),dt.getMonth(),dt.getDate()).getTime())/86400000));
  };
  const clientMap=new Map();
  clientRows.forEach(function(c){
    const obj={
      id:String(c.id||c.name||''),
      name:String(c.name||c.patient_name||c.id||''),
      mob:String(c.mob||c.mobile||c.mobile_no||''),
      br:brCode(c.br||c.branch||c.branch_name),
      tr:[]
    };
    if(obj.id)clientMap.set(obj.id,obj);
    if(obj.name)clientMap.set(obj.name.toLowerCase(),obj);
  });

  const itemMap=new Map();
  itemRows.forEach(function(it){
    itemMap.set(String(it.code||it.item_code||''),it);
  });

  /* Some live Material Requests may reference items outside the current item
     payload/filter. Add a lightweight live item row so the original PDF
     renderer never falls back to demo data or crashes on ITEM(code). */
  rows.forEach(function(r){
    const ic=String(r.item||'');
    if(!ic||itemMap.has(ic))return;
    const liveItem={
      code:ic,
      item_code:ic,
      name:String(r.itemName||ic),
      item_name:String(r.itemName||ic),
      unit:String(r.unit||''),
      stock_uom:String(r.unit||''),
      cat:String(r.expectedTreatmentCategory||'Sale Product'),
      item_group:String(r.expectedTreatmentCategory||'Sale Product'),
      type:String(r.stockType||r.requestType||'')
    };
    itemRows.push(liveItem);
    itemMap.set(ic,liveItem);

    if(!ITEMS.some(function(x){return String(x.code||x.item_code||'')===ic})){
      ITEMS.push({
        code:ic,
        name:liveItem.name,
        cat:catOf(liveItem.cat),
        type:stOf(liveItem.type,!!r.client),
        unit:liveItem.unit||'Unit',
        reorder:0,
        since:'',
        icon:'📦'
      });
    }
  });

  const dispatchMap=new Map();
  dispatchRows.forEach(function(x){
    const req=String(x.material_request||x.ind||'');
    const item=String(x.item||'');
    if(req&&item)dispatchMap.set(req+'||'+item,x);
  });

  CLIENTS.splice(0,CLIENTS.length);
  CSTK.splice(0,CSTK.length);
  SREQ.splice(0,SREQ.length);

  const treatSeen=new Map();

  rows.forEach(function(r){
    const clientKey=String(r.client||'');
    let c=clientMap.get(clientKey)||clientMap.get(clientKey.toLowerCase());
    if(!c&&clientKey){
      c={id:clientKey,name:clientKey,mob:String(r.mobile||''),br:brCode(r.branch||r.br),tr:[]};
      clientMap.set(clientKey,c);clientMap.set(clientKey.toLowerCase(),c);
    }

    const itemCode=String(r.item||'');
    const it=itemMap.get(itemCode)||{};
    const br=brCode(r.branch||r.br||r.target_warehouse||'');
    const cat=catOf(r.expectedTreatmentCategory||r.therapy_type||r.treatmentCategory||it.cat||it.item_group||'');
    const st=stOf(it.type||r.stockType||r.requestType||'',!!c);
    const reqQty=Number(r.reqQty!=null?r.reqQty:(r.qty||0))||0;
    const recQty=Number(r.recQty!=null?r.recQty:(r.receivedQty||0))||0;
    const releasedQty=Number(r.releasedQty!=null?r.releasedQty:recQty)||0;
    const pendingQty=Number(r.pendingQty!=null?r.pendingQty:Math.max(reqQty-recQty,0))||0;
    const missingQty=Number(r.missingQty||0)||0;
    const damagedQty=Number(r.damagedQty||0)||0;
    const returnQty=Number(r.returnQty||0)||0;
    const reqDate=String(r.reqDate||r.date||'');
    const reqAg=daysAgo(reqDate);
    const requestId=String(r.req||r.id||'');
    const dispatch=dispatchMap.get(requestId+'||'+itemCode)||{};
    const recvDate=String(r.receiptReportedOn||dispatch.recvDate||dispatch.date||'');
    const recAg=recvDate?daysAgo(recvDate):(recQty>0?reqAg:null);
    const status=String(r.status||'Pending');
    const transit=/transit/i.test(status)||(/approved/i.test(status)&&releasedQty>0&&recQty<=0);
    const reqByName=String(
      r.requestByName||
      r.request_by_name||
      r.requestBy||
      r.reqBy||
      r.owner||
      ''
    ).trim();
    const reqByRole=String(
      r.requestByRole||
      r.request_by_role||
      r.reqByRole||
      ''
    ).trim();
    const reqBy={n:reqByName||'—',r:reqByRole};
    const treat=String(r.therapy||r.appointment||r.expectedTreatmentCategory||'');
    const approvedQty=(
      r.approvedQty!==null &&
      r.approvedQty!==undefined &&
      r.approvedQty!==''
    )
      ? Number(r.approvedQty)
      : null;

    let rejectedQty=0;
    if(/reject/i.test(status)){
      rejectedQty=reqQty;
    }else if(
      /partly approved/i.test(status) &&
      approvedQty!==null
    ){
      rejectedQty=Math.max(reqQty-approvedQty,0);
    }

    // Missing and damaged are the receipt discrepancy quantities.
    // returnQty is NOT added again because the receipt workflow already
    // treats return-to-source as the disposition of missing/damaged stock.
    const adj=missingQty+damagedQty;

    const diff=(
      r.receiptReconciliationDiff!==null &&
      r.receiptReconciliationDiff!==undefined &&
      r.receiptReconciliationDiff!==''
    )
      ? Number(r.receiptReconciliationDiff)
      : null;

    // Current branch physical stock is real ERP stock but cannot be
    // attributed to one specific client/request line. Keep request-level
    // balance null; branch/item summaries use live branch_stock separately.
    const bal=null;

    const executedEvidence=String(
      r.executionEvidence||
      r.execution_evidence||
      ''
    );

    const s={
      br:br,reqBy:reqBy,item:itemCode,cat:cat,st:st,reqQty:reqQty,reqAg:reqAg,reqDate:reqDate,
      id:requestId,cl:c||null,treat:treat,status:status,apr:approvedQty,rej:rejectedQty,
      reason:String(r.discrepancyRemarks||''),apBy:String(r.approvedBy||''),
      from:String(r.source||r.src||dispatch.source||''),
      recAg:recAg,rec:recQty,transit:transit,etd:null,adj:adj,
      adjR:String(r.discrepancyRemarks||r.discrepancyType||''),bal:bal,diff:diff,
      executedEvidence:executedEvidence,
      currentBranchStock:realBranchItemBalanceFromPayload(d,itemCode,br),
      requestId:requestId,stockEntry:String(r.stockEntry||dispatch.ref||'')
    };
    SREQ.push(s);

    if(c){
      if(br&&!c.br)c.br=br;
      if(!CLIENTS.includes(c))CLIENTS.push(c);
      if(treat&&!c.tr.some(function(t){return t.n===treat})){
        const tobj={n:treat,cat:cat};c.tr.push(tobj);
        treatSeen.set(treat+'||'+cat,tobj);
      }

      const given=recQty>0;
      const rowQty=recQty||(approvedQty!==null?approvedQty:reqQty);
      const rowRate=Number((it&&((it.rate!=null?it.rate:it.last_purchase_rate)))||0)||0;
      const exactExecutedQty=null;
      const executionFlag=executedEvidence?'Yes':'No';
      const rowPending=given?null:pendingQty;
      const row={
        cl:c,br:br,treat:treat,cat:cat,reqBy:reqBy,item:itemCode,
        itemName:String(r.itemName||it.name||it.item_name||itemCode),
        unit:String(r.unit||it.unit||it.stock_uom||''),
        st:st,
        reqQty:reqQty,reqAg:reqAg,reqDate:reqDate,sr:s,
        ex:exactExecutedQty,etdAg:null,etdDate:'',adj:adj,
        adjR:s.adjR,rcvdBy:null,gAg:recAg,
        givenDate:recvDate?String(recvDate).slice(0,10):'',
        gState:given?'Given':(transit?'In transit':(/approved/i.test(status)?'Approved / awaiting receipt':'Awaiting approval')),
        src:String(dispatch.source||r.source||r.src||''),
        qty:rowQty,
        worth:rowQty*rowRate,
        flag:executionFlag,
        executedEvidence:executedEvidence,
        pend:rowPending,
        pAge:(rowPending>0?reqAg:null)
      };
      const recvBy=String(r.receiptReportedBy||dispatch.recvBy||'');
      if(recvBy)row.rcvdBy={n:recvBy,r:'Stores'};
      CSTK.push(row);
    }
  });

  CLIENTS.sort(function(a,b){return a.name.localeCompare(b.name)});
  SREQ.sort(function(a,b){return b.reqAg-a.reqAg||String(a.br||'').localeCompare(String(b.br||''))});
  CSTK.sort(function(a,b){return b.reqAg-a.reqAg||String((a.cl&&a.cl.name)||'').localeCompare(String((b.cl&&b.cl.name)||''))});

  /* Replace demo treatment filter values with actual live therapy/appointment values. */
  TREAT.splice(0,TREAT.length);
  treatSeen.forEach(function(t){TREAT.push(t)});
  TREAT.sort(function(a,b){return a.n.localeCompare(b.n)});

  fillSR();
  S.cSel='';
  S.cSort={k:'req',d:-1};
  S.sSort={k:'req',d:-1};
  renderSR();

  const n1=document.getElementById('srN1');
  const n2=document.getElementById('srN2');
  if(n1)n1.textContent=CSTK.length+' lines';
  if(n2)n2.textContent=SREQ.length+' requests';
  console.info('[LIFE Stores 360 Reports hydrated]',{clients:CLIENTS.length,client_lines:CSTK.length,status_requests:SREQ.length,treatments:TREAT.length});
};


