    /* Also derive item/vendor relationships from real purchase rows. */
    (d.purchases||[]).forEach(function(p){
      const ic=String(p.item||''),vc=vendorCode(p.vendor||'');
      if(!ic||!vc)return;
      if(!itemVendors[ic])itemVendors[ic]=[];
      if(itemVendors[ic].indexOf(vc)<0)itemVendors[ic].push(vc);
    });

    PURCHASES.splice(0,PURCHASES.length);
    (d.purchases||[]).forEach(function(p){
      PURCHASES.push({
        po:String(p.po||''),inv:String(p.inv||p.receipt||''),grn:String(p.grn||p.inv||p.receipt||''),
        date:String(p.date||''),recvDate:String(p.recvDate||p.date||''),vendor:vendorCode(p.vendor||p.vendor_name||''),
        item:String(p.item||''),qty:num(p.qty||p.usable_qty),rate:num(p.rate),val:num(p.val||p.amount),
