      DISPATCH.push({
        ind:String(x.ind||x.material_request||x.ref||''),challan:String(x.challan||x.ref||''),
        reqDate:String(x.reqDate||x.date||''),reqBy:String(x.reqBy||''),date:String(x.date||''),
        item:String(x.item||''),branch:bc,qty:num(x.qty),rate:num(x.rate),val:num(x.val),
        status:String(x.status||'Received'),recvDate:String(x.recvDate||x.date||''),
