    const bookingAgg={};
    (d.stock_requests||[]).forEach(function(r){
      const ic=String(r.item||'');
      const dt=String(r.reqDate||r.date||'').slice(0,10);
      if(!ic||dt.length<7)return;
      const mon=dt.slice(0,7);
      const key=ic+'||'+mon;
      if(!bookingAgg[key])bookingAgg[key]={item:ic,month:mon,qty:0,open:0};
      bookingAgg[key].qty+=num(r.reqQty!=null?r.reqQty:r.qty);
      bookingAgg[key].open+=num(r.pendingQty);
    });
    Object.keys(bookingAgg).sort().forEach(function(k){BOOKINGS.push(bookingAgg[k])});

