      const box=document.createElement('div');
      box.className='box';

      const title=document.createElement('b');
      title.textContent='Could not load live Stores 360';

      const detail=document.createElement('span');
      detail.textContent=String(msg||'Unknown error');

      const retry=document.createElement('button');
      retry.type='button';
      retry.className='btn';
      retry.style.marginTop='12px';
      retry.textContent='↻ Retry';
      retry.onclick=function(){
        window.location.reload();
      };

      box.appendChild(title);
      box.appendChild(detail);
      box.appendChild(retry);

      el.innerHTML='';
      el.appendChild(box);
    }
  }

  function apiUrl(){
    var fromEl=document.getElementById('fFrom');
    var toEl=document.getElementById('fTo');

    var from=fromEl?String(fromEl.value||''):'';
    var to=toEl?String(toEl.value||''):'';

    var qs=new URLSearchParams();

    if(from)qs.set('from',from);
    if(to)qs.set('to',to);

    return '/api/method/'+API+(qs.toString()?'?'+qs.toString():'');
  }

  function ensureFastInitialDates(){
    var period=document.getElementById('fPeriod');
    var fromEl=document.getElementById('fFrom');
    var toEl=document.getElementById('fTo');

    if(period && !period.value){
      period.value='30';
    }

    if(period && period.value==='365' && !fromEl.value && !toEl.value){
      period.value='30';
    }

    if(toEl && !toEl.value){
      toEl.value=iso(TODAY);
    }

    if(fromEl && !fromEl.value){
      fromEl.value=iso(dAgo(30));
    }
  }

  var lifeLoadController=null;
  var lifeLoadSeq=0;
  var LIFE_FAST_CACHE_PREFIX='LIFE_STORES_360_V259_';
  var LIFE_FAST_CACHE_MAX_AGE=5*60*1000; // show at most 5-minute-old cache, then refresh live in background

  function lifeFastCacheKey(){
    var fromEl=document.getElementById('fFrom');
    var toEl=document.getElementById('fTo');
    return LIFE_FAST_CACHE_PREFIX+String(fromEl&&fromEl.value||'')+'_'+String(toEl&&toEl.value||'');
  }

  function saveLifeFastCache(d){
    try{
      sessionStorage.setItem(lifeFastCacheKey(),JSON.stringify({ts:Date.now(),data:d}));
    }catch(cacheWriteError){
      /* Payload can exceed browser storage quota; live loading continues normally. */
      console.debug('[Stores 360 cache skipped]',cacheWriteError&&cacheWriteError.message);
    }
  }

  function applyLifeFastCache(){
    try{
      var raw=sessionStorage.getItem(lifeFastCacheKey());
      if(!raw)return false;
      var pack=JSON.parse(raw);
      if(!pack||!pack.data||!Array.isArray(pack.data.items))return false;
      if(!pack.ts || (Date.now()-Number(pack.ts))>LIFE_FAST_CACHE_MAX_AGE)return false;

      var d=pack.data;
      lifeApplyUserFromPayload(d);
      window.LIFE_STORES_360_PAYLOAD=d;
      window.LIFE_STORES_360_REPORTS_READY=false;
      window.LIFE_STORES_360_VERSION='V25_9_FAST_REFRESH_CACHE';
      applyMain(d);

      var count=(d.stock_requests||[]).length;
      var pill=document.getElementById('dataPill');
      if(pill)pill.textContent=count.toLocaleString('en-IN')+' records in view';
      var cnt=document.getElementById('tabCnt1');
      if(cnt)cnt.textContent=(d.meta&&d.meta.counts&&d.meta.counts.stock_request_lines)||count;
      done();
      console.info('[Stores 360] fast refresh cache shown; live data refreshing in background');
      return true;
    }catch(cacheReadError){
      try{sessionStorage.removeItem(lifeFastCacheKey())}catch(ignore){}
      return false;
    }
  }

  async function load(){
    ensureFastInitialDates();

    lifeLoadSeq+=1;
    var thisLoadSeq=lifeLoadSeq;

    if(lifeLoadController){
      try{lifeLoadController.abort();}catch(ignoreAbort){}
    }

    var controller=new AbortController();
    lifeLoadController=controller;
    var timer=setTimeout(function(){
      controller.abort();
    },25000);

    try{
      var response=await fetch(apiUrl(),{
        method:'GET',
        credentials:'same-origin',
        headers:{
          'Accept':'application/json',
          'X-Frappe-CSRF-Token':
            (
              window.frappe &&
              frappe.csrf_token
            )
              ? frappe.csrf_token
              : ''
        },
        signal:controller.signal
      });

      var rawText=await response.text();
      var payload={};

      try{
        payload=rawText?JSON.parse(rawText):{};
      }catch(parseError){
        console.error(
          '[LIFE Stores 360 JSON parse]',
          parseError,
          rawText.slice(0,1000)
        );

        fail(
          'Server returned invalid JSON. HTTP '+
          response.status
        );
        return;
      }

      if(!response.ok){
        console.error(
          '[LIFE Stores 360 HTTP]',
          response.status,
          payload
        );

        var serverMessage=
          payload.exception ||
          payload.exc_type ||
          payload.message ||
          '';

        fail(
          'API HTTP '+response.status+
          (serverMessage?' · '+String(serverMessage):'')
        );
        return;
      }

      var d=(
        payload &&
        payload.message !== undefined
      )
        ? payload.message
        : payload;

      if(thisLoadSeq!==lifeLoadSeq){
        return;
      }

      if(!d || !Array.isArray(d.items)){
        var receivedKeys=(d && typeof d==='object')
          ? Object.keys(d).join(', ')
          : typeof d;

        console.error(
          '[LIFE Stores 360 payload incomplete]',
          d
        );

        fail(
          'Main API returned the wrong payload. Received: '+
          (receivedKeys||'empty response')+
          '. Keep only API Method life_stores_360_live_api and paste the V17 real-data-only server script.'
        );
        return;
      }

      saveLifeFastCache(d);

      try{
        lifeApplyUserFromPayload(d);

        /* V19.2: publish the live payload BEFORE rendering.
           Reports may already be the active tab while the API finishes. */
        window.LIFE_STORES_360_PAYLOAD=d;
        window.LIFE_STORES_360_REPORTS_READY=false;
        window.LIFE_STORES_360_VERSION='V22_6_VENDOR_ITEM_NAMES';

        applyMain(d);

        /* V25.9 FAST REFRESH: Reports is expensive. Keep the live payload ready,
           but hydrate the Reports adapter only when the user actually opens Reports. */
        window.LIFE_STORES_360_REPORTS_READY=false;

        var count=(d.stock_requests||[]).length;

        var pill=document.getElementById('dataPill');
        if(pill){
          pill.textContent=
            count.toLocaleString('en-IN')+
            ' records in view';
        }

        var cnt=document.getElementById('tabCnt1');
        if(cnt){
          cnt.textContent=(
            d.meta &&
            d.meta.counts &&
            d.meta.counts.stock_request_lines
          )
            ? d.meta.counts.stock_request_lines
            : count;
        }

        done();

      }catch(applyError){
        console.error(
          '[LIFE Stores 360 live apply]',
          applyError
        );

        fail(
          applyError &&
          applyError.message
            ? applyError.message
            : String(applyError)
        );
      }

    }catch(fetchError){
      console.error(
        '[LIFE Stores 360 fetch]',
        fetchError
      );

      if(fetchError && fetchError.name==='AbortError'){
        if(thisLoadSeq!==lifeLoadSeq){
          return;
        }
        fail(
          'Live data request timed out after 25 seconds. The server query is still too heavy.'
        );
      }else{
        fail(
          'Could not connect to life_stores_360_live_api.'
        );
      }

    }finally{
      clearTimeout(timer);
    }
  }

  window.LIFE_STORES_360_RELOAD=function(){
    var loader=document.getElementById('lifeLiveLoading');
    if(loader){
      loader.style.display='flex';
      loader.innerHTML='<div class="box"><b>Refreshing Stores 360</b><span>Loading selected period…</span></div>';
    }
    return load();
  };

  ensureFastInitialDates();
  var lifeHadFastCache=applyLifeFastCache();
  /* Cached data makes browser refresh immediate. A live API request still runs
     in the background and replaces it as soon as ERPNext responds. */
  setTimeout(load,lifeHadFastCache?80:0);
})();


})();

