    const search=document.getElementById('srsItem');
    const reset=document.getElementById('srsReset');
    const print=document.getElementById('srsPrint');
    const dlBtn=document.querySelector('[data-ddbtn="s"]');
    if(!diff||!search||!reset||!print||!dlBtn)return false;

    const diffWrap=fieldWrap(diff);
    const searchWrap=fieldWrap(search);
    if(!diffWrap||!searchWrap)return false;

    let row=document.getElementById('life-srs-inline-v2526');
    if(!row){
      row=document.createElement('div');
      row.id='life-srs-inline-v2526';
      row.className='life-srs-inline-v2526';
      diffWrap.insertAdjacentElement('afterend',row);
    }

    /* Search stays as a complete labeled field. */
    if(searchWrap.parentElement!==row)row.appendChild(searchWrap);

    let actions=document.getElementById('life-srs-inline-actions-v2526');
    if(!actions){
      actions=document.createElement('div');
      actions.id='life-srs-inline-actions-v2526';
      actions.className='life-srs-inline-actions-v2526';
      row.appendChild(actions);
    }

    if(reset.parentElement!==actions)actions.appendChild(reset);
    if(print.parentElement!==actions)actions.appendChild(print);

    const dd=dlBtn.closest('.sr-dd') || dlBtn.parentElement || dlBtn;
    if(dd.parentElement!==actions)actions.appendChild(dd);

    const stId='life-srs-inline-style-v2526';
    if(!document.getElementById(stId)){
      const st=document.createElement('style');
      st.id=stId;
      st.textContent=`
        #life-srs-inline-v2526{
          display:grid!important;
          grid-template-columns:minmax(360px,1fr) auto!important;
          gap:10px!important;
          align-items:end!important;
          flex:1 1 620px!important;
          min-width:520px!important;
          margin:0!important;
        }
        #life-srs-inline-v2526 > *{min-width:0!important;margin:0!important;}
        #life-srs-inline-v2526 input#srsItem{
          width:100%!important;
          min-width:0!important;
          height:43px!important;
        }
        #life-srs-inline-actions-v2526{
          display:flex!important;
          gap:9px!important;
          align-items:center!important;
          justify-content:flex-end!important;
          white-space:nowrap!important;
          padding-bottom:0!important;
        }
        #life-srs-inline-actions-v2526 button,
        #life-srs-inline-actions-v2526 .btn{
          height:38px!important;
          min-height:38px!important;
          margin:0!important;
        }
        /* Force the second status-filter line to use the full width compactly. */
        #pgSR .life-srs-inline-v2526{align-self:end!important;}
        @media(max-width:1250px){
          #life-srs-inline-v2526{grid-template-columns:1fr!important;min-width:360px!important;}
          #life-srs-inline-actions-v2526{justify-content:flex-start!important;}
        }
        @media(max-width:700px){
          #life-srs-inline-v2526{min-width:0!important;width:100%!important;}
          #life-srs-inline-actions-v2526{flex-wrap:wrap!important;}
        }
      `;
      (document.head||document.documentElement).appendChild(st);
    }
    return true;
  }

  if(!apply()){
    let tries=0;
    const t=setInterval(function(){
      tries++;
      if(apply()||tries>30)clearInterval(t);
    },150);
  }

  document.querySelectorAll('.tab').forEach(function(t){
    t.addEventListener('click',function(){setTimeout(apply,0);});
  });
})();



