  if(old)old.remove();

  var st=document.createElement('style');
  st.id='life-client-filter-layout-v2541';
  st.textContent=`
    /* Client report filter card */
    #srClient .sr-filter,
    #srClient .filterbox,
    #srClient .filters,
    #srClient .sr-card:first-child{
      padding:14px 18px 14px!important;
    }

    /* Main filter grid */
    #srClient .src-filter-grid,
    #srClient .sr-fg,
    #srClient .filter-grid{
      display:grid!important;
      grid-template-columns:
        1.05fr 1.05fr 1.05fr 1.75fr 1.05fr 1.9fr 1.55fr!important;
