       top filter controls into a clean 7-column grid by using their parent. */
    #srClient:has(#srcPeriod) #srcPeriod,
    #srClient:has(#srcFrom) #srcFrom,
    #srClient:has(#srcTo) #srcTo,
    #srClient:has(#srcBr) #srcBr,
    #srClient:has(#srcCat) #srcCat,
    #srClient:has(#srcTreat) #srcTreat,
    #srClient:has(#srcSt) #srcSt,
    #srClient:has(#srcExec) #srcExec,
    #srClient:has(#srcAge) #srcAge,
    #srClient:has(#srcBy) #srcBy{
      width:100%!important;
      min-width:0!important;
      max-width:none!important;
      box-sizing:border-box!important;
    }

    /* Labels */
    #srClient label,
    #srClient .lbl,
    #srClient .flabel{
      display:block!important;
      margin:0 0 5px!important;
      font-size:11px!important;
      line-height:1.05!important;
      font-weight:900!important;
      letter-spacing:.28px!important;
    }

    /* Controls */
    #srClient select,
    #srClient input[type="date"],
    #srClient input[type="text"],
    #srClient input[type="search"]{
      height:40px!important;
      min-height:40px!important;
      padding:6px 10px!important;
      font-size:12.5px!important;
      border-radius:10px!important;
    }

    /* Explicit widths for the visible top-row filters */
    #srcPeriod{min-width:150px!important}
    #srcFrom,#srcTo{min-width:150px!important}
    #srcBr{min-width:250px!important}
    #srcCat{min-width:170px!important}
    #srcTreat{min-width:285px!important}
    #srcSt{min-width:235px!important}

    /* Second row should not leave a large empty area */
    #srcExec{min-width:175px!important}
    #srcAge{min-width:175px!important}
    #srcBy{min-width:285px!important}

    /* Reduce vertical gap between row 1 and row 2 */
    #srClient .filter-row,
    #srClient .frow,
    #srClient .row{
      row-gap:10px!important;
      column-gap:14px!important;
    }

    /* Find the closest wrappers around the top 10 controls and arrange them */
    #srClient .life-client-filter-grid-v2541{
      display:grid!important;
      grid-template-columns:
        minmax(150px,1fr)
        minmax(150px,1fr)
        minmax(150px,1fr)
        minmax(250px,1.55fr)
        minmax(170px,1fr)
        minmax(285px,1.75fr)
        minmax(235px,1.45fr)!important;
      gap:10px 14px!important;
      align-items:end!important;
      width:100%!important;
    }

    #srClient .life-client-filter-grid-v2541 .life-client-filter-cell{
      min-width:0!important;
      width:100%!important;
      margin:0!important;
    }

    /* Put row-2 controls tightly under row 1 */
    #srClient .life-client-filter-grid-v2541 .life-cell-srcExec{
      grid-column:1 / 2!important;
    }
    #srClient .life-client-filter-grid-v2541 .life-cell-srcAge{
      grid-column:2 / 3!important;
    }
    #srClient .life-client-filter-grid-v2541 .life-cell-srcBy{
      grid-column:3 / 5!important;
    }

    /* Keep remaining columns empty only when needed; no giant bottom gap */
    #srClient .life-client-filter-grid-v2541{
      padding-bottom:0!important;
      margin-bottom:0!important;
    }

    @media(max-width:1500px){
      #srClient .life-client-filter-grid-v2541{
        grid-template-columns:repeat(4,minmax(180px,1fr))!important;
      }
      #srClient .life-client-filter-grid-v2541 .life-cell-srcExec,
      #srClient .life-client-filter-grid-v2541 .life-cell-srcAge,
      #srClient .life-client-filter-grid-v2541 .life-cell-srcBy{
        grid-column:auto!important;
      }
    }

    @media(max-width:1000px){
      #srClient .life-client-filter-grid-v2541{
        grid-template-columns:repeat(2,minmax(0,1fr))!important;
      }
    }

    @media(max-width:620px){
      #srClient .life-client-filter-grid-v2541{
        grid-template-columns:1fr!important;
      }
    }
  `;
  (document.head||document.documentElement).appendChild(st);

  function wrapFor(el){
    if(!el)return null;
    return el.closest('.fg,.field,.filter-field,.form-group,.control-group,.filter-item') || el.parentElement;
  }

  function apply(){
    var host=document.querySelector('#srClient');
    if(!host || host.dataset.lifeClientFilterLayoutV2541==='1')return;

    var ids=['srcPeriod','srcFrom','srcTo','srcBr','srcCat','srcTreat','srcSt','srcExec','srcAge','srcBy'];
    var wraps=ids.map(function(id){
      var el=document.getElementById(id);
      var w=wrapFor(el);
      if(w){
        w.classList.add('life-client-filter-cell','life-cell-'+id);
      }
      return w;
    }).filter(Boolean);

    if(wraps.length<8)return;

    var first=wraps[0];
    var parent=first.parentElement;
    if(!parent)return;

    var grid=document.createElement('div');
    grid.className='life-client-filter-grid-v2541';

    wraps.forEach(function(w){
      grid.appendChild(w);
    });

    parent.insertBefore(grid,parent.firstChild);
    host.dataset.lifeClientFilterLayoutV2541='1';
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){setTimeout(apply,0);});
  }else{
    setTimeout(apply,0);
  }
})();
